window.LESSONS=[{"day":1,"title":"OTEL VE KONAKLAMA HİZMETLERİNDE TÜRKÇE","subtitle":"1.1. RESEPSİYON — MİSAFİR KARŞILAMA VE KONAKLAMA İŞLEMLERİ","words":[["1","Resepsiyon","Resepsiyon, qabulxona"],["2","Misafir","Mehmon"],["3","Rezervasyon","Bron"],["4","Oda","Xona"],["5","Tek kişilik oda","Bir kishilik xona"],["6","Çift kişilik oda","Ikki kishilik xona"],["7","Anahtar","Kalit"],["8","Kart","Karta"],["9","Giriş","Kirish"],["10","Çıkış","Chiqish"],["11","Konaklama","Mehmonxonada qolish"],["12","Kahvaltı","Nonushta"],["13","Pasaport","Pasport"],["14","Kimlik","Shaxsni tasdiqlovchi hujjat"],["15","Boş","Bo‘sh"],["16","Dolu","Band, to‘la"],["17","Kat","Qavat"],["18","Asansör","Lift"],["19","Ücret","To‘lov, narx"],["20","Bagaj","Bagaj, yuk"]],"phrases":[["1","Hoş geldiniz.","Xush kelibsiz."],["2","Size nasıl yardımcı olabilirim?","Sizga qanday yordam bera olaman?"],["3","Size yardımcı olabilir miyim?","Sizga yordam bera olamanmi?"],["4","Rezervasyonunuz var mı?","Broningiz bormi?"],["5","Rezervasyonunuz hangi isimle?","Bron kimning nomiga?"],["6","Rezervasyonunuzu kontrol ediyorum.","Broningizni tekshiryapman."],["7","Bir dakika, lütfen.","Bir daqiqa, iltimos."],["8","Pasaportunuzu görebilir miyim?","Pasportingizni ko‘rsam bo‘ladimi?"],["9","Kimliğinizi alabilir miyim?","Shaxsiy hujjatingizni olsam bo‘ladimi?"],["10","Odanız hazır.","Xonangiz tayyor."],["11","Odanız henüz hazır değil.","Xonangiz hali tayyor emas."],["12","Odanız üçüncü katta.","Xonangiz uchinchi qavatda."],["13","Asansör sağ tarafta.","Lift o‘ng tomonda."],["14","Kahvaltı saat yedide başlıyor.","Nonushta soat yettida boshlanadi."],["15","Kahvaltı fiyata dahil.","Nonushta narxga kiritilgan."],["16","Odanızda herhangi bir sorun var mı?","Xonangizda biror muammo bormi?"],["17","Başka bir isteğiniz var mı?","Yana biror istagingiz bormi?"],["18","Elbette, hemen yardımcı olalım.","Albatta, darhol yordam beraylik."],["19","Maalesef şu anda müsait odamız yok.","Afsuski, hozir bo‘sh xonamiz yo‘q."],["20","Sizin için başka bir oda kontrol edebilirim.","Siz uchun boshqa xonani tekshirib ko‘rishim mumkin."],["21","Rezervasyonunuzu değiştirmek ister misiniz?","Broningizni o‘zgartirmoqchimisiz?"],["22","Çıkış saatiniz nedir?","Chiqish vaqtingiz qachon?"],["23","Çıkış işleminizi yapabiliriz.","Chiqish jarayoningizni amalga oshirishimiz mumkin."],["24","Bagajınızı burada bırakabilirsiniz.","Bagajingizni shu yerda qoldirishingiz mumkin."],["25","Odanızın anahtarını teslim edebilir misiniz?","Xona kalitini topshira olasizmi?"],["26","Ödemenizi kartla yapabilirsiniz.","To‘lovni karta orqali qilishingiz mumkin."],["27","Faturanızı hazırlıyorum.","Hisob-fakturangizni tayyorlayapman."],["28","Beklettiğimiz için özür dileriz.","Kuttirib qo‘yganimiz uchun uzr so‘raymiz."],["29","Yaşadığınız sorun için üzgünüz.","Siz duch kelgan muammo uchun afsusdamiz."],["30","İyi konaklamalar, tekrar bekleriz.","Yaxshi dam oling, yana kutib qolamiz."]],"dialogs":[{"title":"DİYALOG 1 — MİSAFİRİ KARŞILAMA VE CHECK-IN","lines":["Durum: Misafir otele gelir. Rezervasyonu sistemde bulunur ve resepsiyon görevlisi giriş işlemlerini gerçekleştirir.","Resepsiyon: Hoş geldiniz. Size nasıl yardımcı olabilirim?","Misafir: Merhaba. Benim adıma bir rezervasyon olması gerekiyor. İki gece için oda ayırtmıştım.","Resepsiyon: Tabii. Rezervasyonunuz hangi isimle yapılmıştı?","Misafir: Mehmet Yılmaz adına.","Resepsiyon: Bir dakika, lütfen. Sistemi kontrol ediyorum. Evet, Mehmet Yılmaz adına iki gecelik bir rezervasyon görüyorum. Çift kişilik oda, doğru mu?","Misafir: Evet, doğru.","Resepsiyon: Harika. Pasaportunuzu görebilir miyim?","Misafir: Tabii, buyurun.","Resepsiyon: Teşekkür ederim. Odanız hazır. Üçüncü katta, 305 numaralı oda. Kahvaltınız da konaklama ücretine dahil.","Misafir: Kahvaltı saat kaçta başlıyor?","Resepsiyon: Sabah saat yedide başlıyor ve saat ona kadar devam ediyor.","Misafir: Çok iyi. Wi-Fi şifresini nereden alabilirim?","Resepsiyon: Wi-Fi bilgileri odanızdaki masanın üzerinde bulunan kartta yazıyor. Herhangi bir sorun yaşarsanız veya başka bir şeye ihtiyacınız olursa resepsiyonu arayabilirsiniz.","Misafir: Çok teşekkür ederim.","Resepsiyon: Rica ederim. Otelimize hoş geldiniz. Size güzel bir konaklama dileriz."]},{"title":"DİYALOG 2 — ODA HENÜZ HAZIR DEĞİL","lines":["Durum: Misafirin odası henüz hazır değildir. Resepsiyon görevlisi durumu açıklar ve çözüm sunar.","Misafir: Merhaba. Rezervasyonum var. Odamın hazır olduğunu düşünüyordum.","Resepsiyon: Hoş geldiniz. Rezervasyonunuzu hemen kontrol edeyim. Hangi isimle yapılmıştı?","Misafir: Ayşe Demir adına.","Resepsiyon: Teşekkür ederim. Evet, rezervasyonunuzu buldum. Maalesef odanız şu anda henüz hazır değil. Bunun için özür dileriz.","Misafir: Ne kadar beklemem gerekiyor? Biraz yorgunum ve odaya çıkıp dinlenmek istiyorum.","Resepsiyon: Sizi anlıyorum. Housekeeping ekibimiz odayı hazırlıyor. Yaklaşık yirmi dakika içinde hazır olmasını bekliyoruz.","Misafir: Peki, bu süre içinde ne yapabilirim?","Resepsiyon: Bagajınızı burada güvenli bir şekilde bırakabilirsiniz. İsterseniz lobimizde dinlenebilirsiniz. Odanız hazır olduğunda sizi hemen bilgilendireceğiz.","Misafir: Tamam, teşekkür ederim. Bagajımı burada bırakayım.","Resepsiyon: Elbette. Bagajınızı güvenli bir şekilde muhafaza edeceğiz. Beklettiğimiz için tekrar özür dileriz.","Misafir: Sorun değil. Teşekkür ederim.","Resepsiyon: Rica ederim. Odanız hazır olur olmaz sizi arayacağız."]},{"title":"DİYALOG 3 — REZERVASYONDA HATA","lines":["Durum: Misafir tek kişilik oda rezervasyonu yaptığını düşünmektedir ancak sistemde farklı bir oda türü görünmektedir.","Misafir: Merhaba. Ben tek kişilik oda rezervasyonu yapmıştım ama bana verilen oda iki kişilik görünüyor.","Resepsiyon: Anladım. Öncelikle yaşadığınız durum için özür dilerim. Rezervasyonunuzu tekrar kontrol edeyim.","Misafir: Tabii. Çünkü özellikle tek kişilik oda seçmiştim.","Resepsiyon: Haklısınız. Sistemde rezervasyonunuzun tek kişilik oda olarak oluşturulduğunu görüyorum. Ancak oda atamasında bir hata olmuş olabilir.","Misafir: Peki, ne yapabiliriz?","Resepsiyon: Hemen müsait odalarımızı kontrol ediyorum. Bir dakika lütfen.","Misafir: Tamam.","Resepsiyon: Evet, sizin için uygun bir tek kişilik odamız var. İsterseniz hemen o odaya geçebilirsiniz.","Misafir: Çok iyi olur. Teşekkür ederim.","Resepsiyon: Rica ederim. Yeni oda anahtarınızı hazırlıyorum. Bagajınızı da personelimiz yeni odanıza taşıyabilir.","Misafir: Çok teşekkürler. Sorunu hızlı çözdüğünüz için memnun oldum.","Resepsiyon: Biz teşekkür ederiz. Yaşanan karışıklık için tekrar özür dileriz. Başka bir isteğiniz olursa lütfen bize bildirin."]},{"title":"DİYALOG 4 — MİSAFİR EŞYASINI OTELDE UNUTUYOR","lines":["Durum: Misafir otelden ayrıldıktan sonra odasında telefon şarj cihazını unuttuğunu fark eder.","Misafir: Merhaba. Az önce otelden ayrıldım ama odada telefon şarj cihazımı unuttuğumu düşünüyorum.","Resepsiyon: Tabii, size yardımcı olalım. Hangi odada kalmıştınız?","Misafir: 214 numaralı odada kaldım.","Resepsiyon: Adınızı alabilir miyim?","Misafir: Ahmet Kaya.","Resepsiyon: Teşekkür ederim. Hemen housekeeping bölümümüzle iletişime geçiyorum. Lütfen hatta kalın.","Misafir: Tamam, bekliyorum.","Resepsiyon: Housekeeping ekibiyle görüştüm. Odanız kontrol ediliyor.","Misafir: Umarım bulurlar. Şarj cihazı benim için önemli.","Resepsiyon: Anlıyorum. Birkaç dakika içinde size kesin bilgi vereceğiz.","Misafir: Teşekkür ederim.","Resepsiyon: Evet, güzel haber. Odanızda siyah renkli bir telefon şarj cihazı bulunmuş.","Misafir: Gerçekten mi? Çok sevindim.","Resepsiyon: Evet. İsterseniz bugün otelimize gelip teslim alabilirsiniz. Eğer tekrar gelemiyorsanız, kargo seçeneklerini de sizin için kontrol edebiliriz.","Misafir: Bugün gelemem. Kargo ile gönderebilir misiniz?","Resepsiyon: Elbette. Adres bilgilerinizi alalım, kargo ücretini de size bildirelim.","Misafir: Çok teşekkür ederim. Gerçekten yardımcı oldunuz.","Resepsiyon: Rica ederiz. Misafirlerimizin eşyalarının güvenli bir şekilde teslim edilmesi bizim için önemlidir."]}],"grammar":["6. GEREKLİ DİLBİLGİSİ","6.1. “-MI?” SORU EKİ","Türkçede soru sormak için mı, mi, mu, mü soru eki kullanılır. Soru eki ayrı yazılır.","Ek, kelimenin son ünlüsüne göre değişir:","a / ı → mı\ne / i → mi\no / u → mu\nö / ü → mü","Turizm sektöründen örnekler:","Rezervasyonunuz var mı?\nBroningiz bormi?","Odanız hazır mı?\nXonangiz tayyormi?","Kahvaltı dahil mi?\nNonushta kiritilganmi?","Boş odanız var mı?\nBo‘sh xonangiz bormi?","Başka bir isteğiniz var mı?\nYana biror istagingiz bormi?","6.2. “VAR / YOK”","Var — bor, mavjud.","Yok — yo‘q, mavjud emas.","Bu so‘zlar turizmda juda ko‘p ishlatiladi.","Boş odamız var.\nBo‘sh xonamiz bor.","Boş odamız yok.\nBo‘sh xonamiz yo‘q.","Rezervasyonunuz var.\nBrogeniz bor.","Rezervasyonunuz yok.\nBrogeniz yo‘q.","Müsait odamız var mı?\nBo‘sh xonamiz bormi?","Müsait odamız yok.\nBo‘sh xonamiz yo‘q.","6.3. “-EBİLMEK / -ABİLMEK” — YAPABİLMEK","Türkçede -ebilmek / -abilmek bir işi yapabilme anlamı verir. Özbekçedeki “-a olmoq / -y olmoq” ma’nosiga yaqin.","Turizm sektöründe özellikle nazik bir şekilde yardım teklif etmek ve izin istemek için kullanılır.","Örnekler:","Size yardımcı olabilir miyim?\nSizga yordam bera olamanmi?","Pasaportunuzu görebilir miyim?\nPasportingizni ko‘rsam bo‘ladimi?","Bagajınızı taşıyabiliriz.\nBagajingizni olib borishimiz mumkin.","Odanızı değiştirebiliriz.\nXonangizni almashtirishimiz mumkin.","Sizin için rezervasyon yapabilirim.\nSiz uchun bron qilib bera olaman.","Kibar kullanım:","❌ Pasaportunuzu verin.\nPasportingizni bering.","✅ Pasaportunuzu alabilir miyim?\nPasportingizni olsam bo‘ladimi?","Turizm sektöründe ikinci cümle daha nazik ve profesyoneldir.","6.4. “-MAK / -MEK İSTEMEK” — İSTEK BİLDİRME","Bir kişinin yapmak istediği işi belirtmek için -mak / -mek istiyorum yapısı kullanılır.","Bu yapı Özbekçedeki “-moqchiman” ma’nosiga yaqin.","Örnekler:","Rezervasyon yapmak istiyorum.\nBron qilmoqchiman.","Odamı değiştirmek istiyorum.\nXonamni almashtirmoqchiman.","Bir gece daha kalmak istiyorum.\nYana bir kecha qolmoqchiman.","Erken çıkış yapmak istiyorum.\nErtaroq chiqmoqchiman.","Müşterinin isteğini sormak:","Ne yapmak istiyorsunuz?\nNima qilmoqchisiz?","Odanızı değiştirmek mi istiyorsunuz?\nXonangizni o‘zgartirmoqchimisiz?","Rezervasyon yapmak mı istiyorsunuz?\nBron qilmoqchimisiz?","6.5. KİBARLIK İFADELERİ","Turizm sektöründe misafirle iletişim kurarken kibar ve profesyonel bir dil kullanmak çok önemlidir.","Temel ifadeler:","Lütfen — Iltimos","Teşekkür ederim — Rahmat","Rica ederim — Arzimaydi","Affedersiniz — Kechirasiz","Özür dilerim — Uzr so‘rayman","Örnekler:","Lütfen pasaportunuzu verebilir misiniz?\nIltimos, pasportingizni bera olasizmi?","Teşekkür ederim.\nRahmat.","Rica ederim.\nArzimaydi.","Affedersiniz, size bir soru sorabilir miyim?\nKechirasiz, sizga bir savol bersam bo‘ladimi?","Yaşadığınız sorun için özür dileriz.\nSiz duch kelgan muammo uchun uzr so‘raymiz."],"video":"https://youtu.be/QQpnVbw-Wk4?si=t6zLaqeCgLW9Qu67","document":"assets/materials/day1.docx"},{"day":2,"title":"Housekeeping, otelin temizlik ve oda düzeninden sorumlu en önemli bölümlerinden biridir. Housekeeping çalışanları odaların temizlenmesi, yatakların hazırlanması, havlu ve çarşafların değiştirilmesi, eksik malzemelerin tamamlanması ve misafirlerin özel taleplerinin karşılanması gibi birçok görev üstlenir.","subtitle":"Bu bölümde housekeeping çalışanlarının misafirlerle iletişim kurarken ihtiyaç duyacağı temel kelimeler, hazır ifadeler ve gerçek iş durumlarına dayalı diyaloglar ele alınmaktadır.","words":[["1","Housekeeping","Xonalarni tozalash xizmati"],["2","Temizlik","Tozalash"],["3","Temizlemek","Tozalamoq"],["4","Oda","Xona"],["5","Yatak","Karavot"],["6","Çarşaf","Choyshab"],["7","Havlu","Sochiq"],["8","Yastık","Yostiq"],["9","Battaniye","Adyol"],["10","Yorgan","Ko‘rpa"],["11","Banyo","Hammom"],["12","Duş","Dush"],["13","Sabun","Sovun"],["14","Şampuan","Shampun"],["15","Tuvalet","Hojatxona"],["16","Çöp","Axlat"],["17","Çöp kutusu","Axlat qutisi"],["18","Süpürge","Changyutgich / supurgi"],["19","Temiz","Toza"],["20","Kirli","Iflos"],["21","Islak","Ho‘l"],["22","Kuru","Quruq"],["23","Eksik","Yetishmayotgan"],["24","Malzeme","Jihoz / kerakli buyum"],["25","Rahatsız","Bezovta"],["26","Leke","Dog‘"],["27","Koku","Hid"],["28","Arıza","Nosozlik"],["29","Kontrol etmek","Tekshirmoq"],["30","Değiştirmek","Almashtirmoq"]],"phrases":[["1","Günaydın, housekeeping.","Xayrli tong, housekeeping."],["2","Odayı temizlemek için geldim.","Xonani tozalash uchun keldim."],["3","Odayı temizleyebilir miyim?","Xonani tozalasam bo‘ladimi?"],["4","Uygun musunuz?","Sizga hozir qulaymi?"],["5","Müsait misiniz?","Bo‘shmisiz?"],["6","Odanızı temizlememi ister misiniz?","Xonangizni tozalashimni xohlaysizmi?"],["7","Ne zaman temizlik yapmamı istersiniz?","Qachon tozalashimni xohlaysiz?"],["8","Birkaç dakika sürecek.","Bir necha daqiqa vaqt oladi."],["9","Temizlik biraz zaman alabilir.","Tozalash biroz vaqt olishi mumkin."],["10","Havluları değiştirebilir miyim?","Sochiqlarni almashtirsam bo‘ladimi?"],["11","Çarşafları değiştirmemi ister misiniz?","Choyshablarni almashtirishimni xohlaysizmi?"],["12","Ekstra havlu ister misiniz?","Qo‘shimcha sochiq xohlaysizmi?"],["13","Başka bir şeye ihtiyacınız var mı?","Yana biror narsaga ehtiyojingiz bormi?"],["14","Başka bir isteğiniz var mı?","Yana biror istagingiz bormi?"],["15","Hemen getiriyorum.","Darhol olib kelaman."],["16","Hemen ilgileniyorum.","Darhol shug‘ullanaman."],["17","Bir dakika içinde getiririm.","Bir daqiqa ichida olib kelaman."],["18","Odanızı rahatsız etmeyeceğim.","Sizni xonada bezovta qilmayman."],["19","Temizlik için daha sonra gelebilirim.","Tozalash uchun keyinroq kelishim mumkin."],["20","Ne zaman tekrar gelebilirim?","Qachon yana kelsam bo‘ladi?"],["21","Bu havluyu değiştirebilir miyim?","Bu sochiqni almashtirsam bo‘ladimi?"],["22","Odada bir sorun var mı?","Xonada biror muammo bormi?"],["23","Teknik ekibe haber vereceğim.","Texnik xodimlarga xabar beraman."],["24","Bu sorunu hemen bildireceğim.","Bu muammo haqida darhol xabar beraman."],["25","Eksik malzemeleri tamamlayacağım.","Yetishmayotgan buyumlarni to‘ldiraman."],["26","Sabun ve şampuan bırakacağım.","Sovun va shampun qoldiraman."],["27","Çöpleri alabilir miyim?","Axlatlarni olsam bo‘ladimi?"],["28","Lütfen biraz bekleyebilir misiniz?","Iltimos, biroz kuta olasizmi?"],["29","Rahatsız ettiysem özür dilerim.","Bezovta qilgan bo‘lsam, uzr so‘rayman."],["30","İyi günler dilerim.","Kuningiz xayrli o‘tsin."]],"dialogs":[{"title":"DİYALOG 1 — ODAYI TEMİZLEMEK İÇİN İZİN İSTEME","lines":["Durum: Housekeeping çalışanı odanın temizliği için kapıyı çalar ve misafirden izin ister.","Housekeeping: Günaydın. Housekeeping.","Misafir: Günaydın.","Housekeeping: Odayı temizlemek için geldim. Uygun musunuz?","Misafir: Şu anda biraz dinleniyorum. Temizliği daha sonra yapabilir misiniz?","Housekeeping: Elbette. Ne zaman tekrar gelebilirim?","Misafir: Yaklaşık bir saat sonra uygun olur.","Housekeeping: Tabii. Bir saat sonra tekrar geleceğim.","Misafir: Teşekkür ederim.","Housekeeping: Rica ederim. Rahatsız ettiysem özür dilerim.","Misafir: Sorun değil.","Housekeeping: İyi dinlenmeler dilerim."]},{"title":"DİYALOG 2 — EKSTRA HAVLU TALEBİ","lines":["Durum: Misafir resepsiyondan ekstra havlu istemiştir. Housekeeping çalışanı havluları odaya getirir.","Housekeeping: Merhaba. Housekeeping. Ekstra havlu istemiştiniz, değil mi?","Misafir: Evet, iki tane ekstra havlu rica etmiştim.","Housekeeping: Tabii. Buyurun, iki temiz havlu getirdim.","Misafir: Çok teşekkür ederim.","Housekeeping: Rica ederim. Başka bir şeye ihtiyacınız var mı?","Misafir: Evet, mümkünse bir tane daha yastık alabilir miyim?","Housekeeping: Elbette. Hemen getiriyorum.","Misafir: Çok teşekkürler.","Housekeeping: Rica ederim. Başka bir isteğiniz olursa lütfen bize bildirin.","Misafir: Tamam, teşekkür ederim.","Housekeeping: İyi günler dilerim."]},{"title":"DİYALOG 3 — TEMİZLİK SIRASINDA MİSAFİR ODADA","lines":["Durum: Çalışan odayı temizlemek için gelir ancak misafir odadadır. Misafir kısa süre sonra dışarı çıkacağını söyler.","Housekeeping: Merhaba. Housekeeping. Odayı temizlemek için geldim. Uygun musunuz?","Misafir: Merhaba. Evet, ama yaklaşık on dakika sonra dışarı çıkacağım.","Housekeeping: İsterseniz siz hazırlanırken banyoyu ve diğer bölümleri temizlemeye başlayabilirim.","Misafir: Olur. Ben de bu sırada hazırlanayım.","Housekeeping: Tabii. Çarşafları ve havluları da değiştirmemi ister misiniz?","Misafir: Evet, lütfen. Havluların hepsini değiştirebilirsiniz.","Housekeeping: Elbette. Çöpleri de alacağım ve eksik malzemeleri tamamlayacağım.","Misafir: Banyoda şampuan da bitmiş.","Housekeeping: Tabii, hemen yeni bir şampuan bırakacağım.","Misafir: Çok teşekkür ederim.","Housekeeping: Rica ederim. Siz dışarı çıktığınızda temizliği tamamlayacağım.","Misafir: Tamam. Kolay gelsin.","Housekeeping: Teşekkür ederim. Size de iyi günler."]},{"title":"DİYALOG 4 — ODADA TEKNİK BİR SORUN","lines":["Durum: Housekeeping çalışanı temizlik sırasında klimada bir sorun fark eder.","Housekeeping: Merhaba. Odanızı temizlemek için geldim.","Misafir: Tabii, buyurun.","Housekeeping: Teşekkür ederim. Odayı temizlerken klimanın düzgün çalışmadığını fark ettim.","Misafir: Evet, ben de dün gece fark ettim. Klima bazen çalışıyor, bazen duruyor.","Housekeeping: Anladım. Bu durumu teknik ekibimize bildireceğim.","Misafir: Ne zaman gelip kontrol edecekler?","Housekeeping: Hemen haber vereceğim. Teknik ekip mümkün olan en kısa sürede odayı kontrol edecektir.","Misafir: Tamam. Çünkü gece oda çok sıcak oluyor.","Housekeeping: Sizi anlıyorum. Yaşadığınız sorun için özür dileriz. İsterseniz resepsiyona da bilgi verebilirim.","Misafir: Evet, lütfen. Resepsiyonun da haberi olsun.","Housekeeping: Elbette. Şimdi bildireceğim. Başka bir sorun var mı?","Misafir: Hayır, başka bir sorun yok.","Housekeeping: Tamam. Teknik ekibin geleceğini size bildireceğiz.","Misafir: Teşekkür ederim.","Housekeeping: Rica ederim. İyi günler dilerim."]}],"grammar":["GEREKLİ DİLBİLGİSİ","5.1. “-İYOR” — ŞİMDİKİ ZAMAN","Türkçede şu anda yapılan veya devam eden işleri anlatmak için -yor eki kullanılır.","Özbekçedeki “-yapman, -yapti, -yapmiz” anlamına yaqin.","Örnekler:","Odayı temizliyorum.\nXonani tozalayapman.","Havluları değiştiriyorum.\nSochiqlarni almashtiryapman.","Odayı kontrol ediyorum.\nXonani tekshiryapman.","Eksik malzemeleri tamamlıyorum.\nYetishmayotgan buyumlarni to‘ldiryapman.","Teknik ekibe haber veriyorum.\nTexnik xodimlarga xabar beryapman.","Soru:","Ne yapıyorsunuz?\nNima qilyapsiz?","Odayı temizliyor musunuz?\nXonani tozalayapsizmi?","Havluları değiştiriyor musunuz?\nSochiqlarni almashtiryapsizmi?","5.2. “-EBİLMEK / -ABİLMEK” — RİCA VE İZİN İSTEME","Housekeeping çalışanları misafirin odasına girmeden önce izin istemelidir. Bunun için -ebilir miyim / -abilir miyim yapısı çok kullanılır.","Örnekler:","Odayı temizleyebilir miyim?\nXonani tozalasam bo‘ladimi?","Havluları değiştirebilir miyim?\nSochiqlarni almashtirsam bo‘ladimi?","Çöpleri alabilir miyim?\nAxlatlarni olsam bo‘ladimi?","Banyoyu kontrol edebilir miyim?\nHammomni tekshirsam bo‘ladimi?","Bu yapı misafirle iletişimde daha kibar bir ifade oluşturur.","5.3. “-MALI / -MELİ” — GEREKLİLİK","Bir işi yapmak gerektiğini belirtmek için -malı / -meli eki kullanılır.","Bu yapı Özbekçedeki “-ish kerak” ma’nosiga yaqin.","Örnekler:","Odayı temizlemeliyim.\nXonani tozalashim kerak.","Havluları değiştirmeliyim.\nSochiqlarni almashtirishim kerak.","Teknik ekibe haber vermeliyiz.\nTexnik xodimlarga xabar berishimiz kerak.","Bu sorunu resepsiyona bildirmeliyiz.\nBu muammo haqida resepsiyonga xabar berishimiz kerak.","Odayı tekrar kontrol etmeliyiz.\nXonani yana tekshirishimiz kerak.","5.4. “-DEN SONRA” — ...DAN KEYIN","Bir işin başka bir işten sonra yapıldığını belirtmek için -den/-dan sonra kullanılır.","Özbekçedeki “-dan keyin” ma’nosini beradi.","Örnekler:","Temizlikten sonra odayı kontrol ederim.\nTozalashdan keyin xonani tekshiraman.","Misafir çıktıktan sonra odayı temizleriz.\nMehmon chiqqandan keyin xonani tozalaymiz.","Temizlikten sonra havluları kontrol ederim.\nTozalashdan keyin sochiqlarni tekshiraman.","5.5. “-MEDEN ÖNCE” — ...DAN OLDIN","Bir işten önce başka bir işin yapıldığını belirtmek için -meden/-madan önce kullanılır.","Özbekçedeki “-dan oldin” ma’nosini beradi.","Örnekler:","Odaya girmeden önce kapıyı çalmalıyız.\nXonaga kirishdan oldin eshikni taqillatishimiz kerak.","Temizliğe başlamadan önce misafire sormalıyız.\nTozalashni boshlashdan oldin mehmondan so‘rashimiz kerak.","Odayı temizlemeden önce misafirin uygun olup olmadığını sormalıyız.\nXonani tozalashdan oldin mehmonning hozir qulay yoki yo‘qligini so‘rashimiz kerak."],"video":"https://youtu.be/V947ASC2YUU?si=TkcN4BPqb_UvVpar","document":"assets/materials/day2.docx"},{"day":3,"title":"KONUYA GİRİŞ","subtitle":"Otel restoranı ve bar bölümü, misafirlerin konaklama deneyiminde önemli bir yere sahiptir. Restoran ve bar çalışanları; misafirleri karşılamak, masa düzenlemek, menüyü tanıtmak, sipariş almak, yiyecek ve içecekleri servis etmek ve ödeme işlemlerini tamamlamak gibi birçok görev üstlenir.","words":[["1","Restoran","Restoran"],["2","Bar","Bar"],["3","Menü","Menyu"],["4","Masa","Stol"],["5","Sandalye","Stul"],["6","Sipariş","Buyurtma"],["7","Sipariş almak","Buyurtma olmoq"],["8","Garson","Ofitsiant"],["9","Müşteri","Mijoz"],["10","Misafir","Mehmon"],["11","Kahvaltı","Nonushta"],["12","Öğle yemeği","Tushlik"],["13","Akşam yemeği","Kechki ovqat"],["14","Yemek","Taom / ovqat"],["15","İçecek","Ichimlik"],["16","Su","Suv"],["17","Çay","Choy"],["18","Kahve","Qahva"],["19","Meyve suyu","Meva sharbati"],["20","Tatlı","Shirinlik"],["21","Ana yemek","Asosiy taom"],["22","Meze","Gazak / zakuska"],["23","Hesap","Hisob"],["24","Ödeme","To‘lov"],["25","Rezervasyon","Bron"],["26","Boş masa","Bo‘sh stol"],["27","Dolu","Band / to‘la"],["28","Servis","Xizmat / servis"],["29","Garson","Ofitsiant"],["30","Şef","Bosh oshpaz"]],"phrases":[["1","Restoranımıza hoş geldiniz.","Restoranimizga xush kelibsiz."],["2","Kaç kişisiniz?","Necha kishisiz?"],["3","Rezervasyonunuz var mı?","Bron qilganmisiz?"],["4","Rezervasyon hangi isimle?","Bron kimning nomiga?"],["5","Buyurun, bu taraftan lütfen.","Marhamat, bu tomonga."],["6","Size uygun bir masa göstereyim.","Sizga mos stol ko‘rsataman."],["7","Menüyü getireyim.","Menyuni olib kelay."],["8","Menümüz burada.","Menyumiz mana bu yerda."],["9","Siparişinizi alabilir miyim?","Buyurtmangizni olsam bo‘ladimi?"],["10","Ne sipariş etmek istersiniz?","Nima buyurtma qilmoqchisiz?"],["11","Ne içmek istersiniz?","Nima ichishni xohlaysiz?"],["12","Size ne ikram edebilirim?","Sizga nima taklif qilsam bo‘ladi?"],["13","Biraz daha bekleyebilir misiniz?","Biroz kutib tura olasizmi?"],["14","Siparişiniz hazırlanıyor.","Buyurtmangiz tayyorlanmoqda."],["15","Siparişiniz birazdan hazır olacak.","Buyurtmangiz birozdan keyin tayyor bo‘ladi."],["16","Yemeğiniz hazır.","Taomingiz tayyor."],["17","Afiyet olsun.","Yoqimli ishtaha."],["18","Başka bir isteğiniz var mı?","Yana biror istagingiz bormi?"],["19","Başka bir şey ister misiniz?","Yana biror narsa xohlaysizmi?"],["20","Kahvenizi nasıl istersiniz?","Qahvangizni qanday xohlaysiz?"],["21","Çayınız şekerli mi olsun?","Choyingiz shakarli bo‘lsinmi?"],["22","Sıcak mı, soğuk mu istersiniz?","Issiqmi yoki sovuqmi xohlaysiz?"],["23","Bu yemek biraz acıdır.","Bu taom biroz achchiq."],["24","Bu yemeğin içinde et var.","Bu taomning ichida go‘sht bor."],["25","Bu yemek vejetaryendir.","Bu taom vegetarianlar uchun."],["26","Maalesef bu yemek kalmadı.","Afsuski, bu taom qolmagan."],["27","Başka bir yemek önerebilirim.","Boshqa taom tavsiya qilishim mumkin."],["28","Hesabınızı getireyim.","Hisobingizni olib kelay."],["29","Ödemeyi nasıl yapmak istersiniz?","To‘lovni qanday amalga oshirmoqchisiz?"],["30","Teşekkür ederiz, yine bekleriz.","Rahmat, yana kutib qolamiz."]],"dialogs":[{"title":"DİYALOG 1 — RESTORANDA MİSAFİRİ KARŞILAMA","lines":["Garson: Restoranımıza hoş geldiniz. Kaç kişisiniz?\nMisafir: Teşekkür ederiz. İki kişiyiz.\nGarson: Rezervasyonunuz var mı?\nMisafir: Evet, rezervasyonumuz var. Ahmet Yılmaz adına.\nGarson: Bir dakika kontrol edeyim. Evet, rezervasyonunuzu buldum. Buyurun, bu taraftan lütfen.\nMisafir: Teşekkür ederiz.\nGarson: Bu masa sizin için uygun mu?\nMisafir: Evet, çok uygun.\nGarson: Buyurun, menüleriniz. Birkaç dakika sonra siparişinizi alabilirim.\nMisafir: Tamam, teşekkür ederiz.\nGarson: Rica ederim. Afiyet olsun.","O‘zbekcha mazmuni:\nOfitsiant mehmonlarni kutib oladi, bronini tekshiradi va ularni mos stolga joylashtiradi."]},{"title":"DİYALOG 2 — SİPARİŞ ALMA","lines":["Garson: Siparişinizi alabilir miyim?\nMisafir: Evet. Ben tavuk yemeği istiyorum.\nGarson: Tabii. Yanında ne almak istersiniz?\nMisafir: Pilav ve salata alabilir miyim?\nGarson: Elbette. İçecek olarak ne istersiniz?\nMisafir: Bir şişe su ve bir çay lütfen.\nGarson: Çayınızı şekerli mi istersiniz, şekersiz mi?\nMisafir: Şekersiz olsun, lütfen.\nGarson: Tabii. Başka bir isteğiniz var mı?\nMisafir: Hayır, teşekkür ederim.\nGarson: Rica ederim. Siparişinizi hemen mutfağa iletiyorum.","O‘zbekcha mazmuni:\nMehmon taom, salat, suv va choy buyurtma qiladi. Ofitsiant buyurtmani aniqlashtirib, oshxonaga yuboradi."]},{"title":"DİYALOG 3 — MENÜDEKİ YEMEĞİN KALMAMASI","lines":["Misafir: Garson, bir şey sorabilir miyim?\nGarson: Tabii, buyurun.\nMisafir: Menüdeki et yemeğini sipariş etmek istiyorum.\nGarson: Maalesef efendim, bugün et yemeğimiz kalmadı.\nMisafir: Gerçekten mi? Ben özellikle onu istiyordum.\nGarson: Özür dilerim. İsterseniz size başka bir yemek önerebilirim.\nMisafir: Ne önerebilirsiniz?\nGarson: Bugün şefimizin özel tavuk yemeği var. Misafirlerimiz çok beğeniyor.\nMisafir: İçinde çok baharat var mı?\nGarson: Hayır, çok baharatlı değil. İsterseniz daha az baharatlı hazırlatabiliriz.\nMisafir: O zaman onu alayım.\nGarson: Tabii efendim. Hemen siparişinizi hazırlatıyorum.","O‘zbekcha mazmuni:\nMehmon tanlagan taom qolmagan. Ofitsiant uzr so‘rab, boshqa taomni tavsiya qiladi va mehmon muqobil variantni tanlaydi."]},{"title":"DİYALOG 4 — SİPARİŞTE HATA","lines":["Misafir: Affedersiniz, ben kahve istemiştim ama bana çay geldi.\nGarson: Çok özür dilerim. Siparişinizi kontrol edeyim.\nMisafir: Ben özellikle kahve istemiştim.\nGarson: Haklısınız. Siparişinizde kahve yazıyor. Mutfak ve servis bölümünde bir karışıklık olmuş.\nMisafir: Ne kadar beklemem gerekiyor?\nGarson: Yaklaşık beş dakika içinde kahvenizi getiriyorum.\nMisafir: Tamam, bekliyorum.\nGarson: Çay için de özür dilerim. İsterseniz bunu masadan kaldırayım.\nMisafir: Evet, lütfen.\nGarson: Tabii. Kahvenizi hemen hazırlatıyorum.\nMisafir: Teşekkür ederim.\nGarson: Asıl biz teşekkür ederiz. Yaşadığınız sorun için tekrar özür dilerim.","O‘zbekcha mazmuni:\nBuyurtmada xatolik yuz beradi. Ofitsiant xatoni tekshiradi, uzr so‘raydi va to‘g‘ri ichimlikni tezda olib kelishni va’da qiladi."]}],"grammar":["GRAMER — GEREKLİ TÜRKÇE","5.1. “-DAN / -DEN” — QAYERDAN, NIMADAN?","-dan / -den qo‘shimchasi biror narsaning qayerdan kelganini yoki nimadan tayyorlanganini bildirishda ishlatiladi.","Restoranda mahsulot va taomlar haqida gapirganda juda foydali.","Örnekler:","Bu yemek tavuktan yapılır.\n— Bu taom tovuq go‘shtidan tayyorlanadi.","Bu tatlı çikolatadan yapılmıştır.\n— Bu shirinlik shokoladdan tayyorlangan.","Kahve Brezilya'dan geliyor.\n— Qahva Braziliyadan keladi.","Müşteri restorandan çıktı.\n— Mijoz restorandan chiqdi.","5.2. “-Lİ / -LİK” — TARKIB VA XUSUSIYATNI BILDIRISH","-li / -lı / -lü / -lu qo‘shimchalari biror narsada ma’lum tarkib yoki xususiyat borligini bildiradi.","Örnekler:","Sütlü kahve ister misiniz?\n— Sutli qahva xohlaysizmi?","Şekerli çay mı istersiniz?\n— Shakarli choy xohlaysizmi?","Etli yemeklerimiz de var.\n— Go‘shtli taomlarimiz ham bor.","Meyveli tatlılarımız çok beğeniliyor.\n— Mevali shirinliklarimiz juda yoqadi.","Baharatlı yemekleri sever misiniz?\n— Ziravorli taomlarni yoqtirasizmi?","5.3. “-SİZ / -SUZ” — BIROR NARSA YO‘QLIGINI BILDIRISH","Bu qo‘shimcha “-siz”, ya’ni biror narsasiz degan ma’noni beradi. Restoranda mijozning maxsus xohishini aniqlashda juda kerak.","Örnekler:","Şekersiz kahve ister misiniz?\n— Shakarsiz qahva xohlaysizmi?","Sütlü mü, sütsüz mü?\n— Sutlimi yoki sutsizmi?","Baharatsız hazırlayabiliriz.\n— Ziravorsiz tayyorlashimiz mumkin.","Tuzsuz yemek istiyorum.\n— Tuzsiz taom xohlayman.","Soğansız olabilir mi?\n— Piyozsiz bo‘lishi mumkinmi?","5.4. “DAHA / EN” — SOLISHTIRISH VA ENG YUQORI DARAJA","Restoranda mijozga turli taomlarni tavsiya qilishda daha va en juda foydali.","Daha — ko‘proq / -roq\nEn — eng","Örnekler:","Bu yemek daha hafif.\n— Bu taom yengilroq.","Bu otelin restoranı daha büyük.\n— Bu mehmonxonaning restorani kattaroq.","Bu tatlı daha popüler.\n— Bu shirinlik mashhurroq.","En çok sipariş edilen yemek budur.\n— Eng ko‘p buyurtma qilinadigan taom shu.","En popüler içeceğimiz Türk kahvesidir.\n— Eng mashhur ichimligimiz turk qahvasidir.","5.5. “-KEN” — ... PAYTIDA / ...GANDA","-ken qo‘shimchasi bir ish sodir bo‘layotgan paytda boshqa ish bajarilishini bildiradi.","Restoran ishida bir vaqtning o‘zida bajariladigan harakatlarni tushuntirishda foydali.","Örnekler:","Misafir yemek yerken garson masayı kontrol eder.\n— Mehmon ovqatlanayotgan paytda ofitsiant stolni tekshiradi.","Müşteri beklerken sipariş hazırlanıyor.\n— Mijoz kutayotgan paytda buyurtma tayyorlanmoqda.","Masayı hazırlarken tabakları kontrol ederim.\n— Stolni tayyorlayotganimda likopchalarni tekshiraman.","Kahve hazırlanırken müşteri bekliyor.\n— Qahva tayyorlanayotgan paytda mijoz kutmoqda."],"video":"https://youtu.be/_Xj9sjfmhOg?si=CFjGRqfgD4qtIHdU","document":"assets/materials/day3.docx"},{"day":4,"title":"2.1. SEYAHAT ACENTESİNDE MÜŞTERİ İLETİŞİMİ","subtitle":"KONUYA GİRİŞ","words":[["1","Seyahat acentesi","Sayohat agentligi"],["2","Müşteri","Mijoz"],["3","Seyahat","Sayohat"],["4","Tur","Tur"],["5","Tatil","Ta’til"],["6","Rezervasyon","Bron"],["7","Uçak bileti","Samolyot chiptasi"],["8","Otel","Mehmonxona"],["9","Konaklama","Joylashish / tunash"],["10","Oda","Xona"],["11","Paket tur","Paket tur"],["12","Tur programı","Tur dasturi"],["13","Fiyat","Narx"],["14","Ücret","To‘lov / xizmat haqi"],["15","Tarih","Sana"],["16","Kalkış","Jo‘nab ketish"],["17","Varış","Yetib borish"],["18","Havalimanı","Aeroport"],["19","Transfer","Transfer"],["20","Rehber","Gid"],["21","Dahil","Kiritilgan"],["22","Hariç","Kiritilmagan"],["23","Müsaitlik","Bo‘sh joy mavjudligi"],["24","İptal","Bekor qilish"],["25","Değişiklik","O‘zgartirish"],["26","Ödeme","To‘lov"],["27","Kapora","Avans"],["28","Kimlik","Shaxsni tasdiqlovchi hujjat"],["29","Pasaport","Pasport"],["30","Sigorta","Sug‘urta"]],"phrases":[["1","Seyahat acentemize hoş geldiniz.","Sayohat agentligimizga xush kelibsiz."],["2","Size nasıl yardımcı olabilirim?","Sizga qanday yordam bera olaman?"],["3","Nasıl bir seyahat planlıyorsunuz?","Qanday sayohat rejalashtiryapsiz?"],["4","Nereye gitmek istiyorsunuz?","Qayerga borishni xohlaysiz?"],["5","Ne zaman seyahat etmek istiyorsunuz?","Qachon sayohat qilmoqchisiz?"],["6","Kaç gün kalacaksınız?","Necha kun qolasiz?"],["7","Kaç kişi seyahat edeceksiniz?","Necha kishi sayohat qilasiz?"],["8","Bütçeniz yaklaşık ne kadar?","Byudjetingiz taxminan qancha?"],["9","Otel tercihiniz var mı?","Mehmonxona bo‘yicha xohishingiz bormi?"],["10","Hangi oteli tercih edersiniz?","Qaysi mehmonxonani afzal ko‘rasiz?"],["11","Size birkaç seçenek sunabilirim.","Sizga bir nechta variant taklif qila olaman."],["12","Bu paket sizin için uygun olabilir.","Bu paket siz uchun mos bo‘lishi mumkin."],["13","Bu fiyata kahvaltı dahildir.","Bu narxga nonushta kiritilgan."],["14","Transfer ücrete dahildir.","Transfer to‘lovga kiritilgan."],["15","Uçak bileti fiyata dahil değildir.","Samolyot chiptasi narxga kiritilmagan."],["16","Bu otelde müsait oda var.","Bu mehmonxonada bo‘sh xona bor."],["17","Bu tarih için yerimiz var.","Bu sana uchun joyimiz bor."],["18","Maalesef bu tarihte müsaitlik yok.","Afsuski, bu sanada bo‘sh joy yo‘q."],["19","Fiyatları kontrol edeyim.","Narxlarni tekshirib olay."],["20","Size en uygun seçeneği bulmaya çalışacağım.","Sizga eng mos variantni topishga harakat qilaman."],["21","Bir dakika, bilgileri kontrol ediyorum.","Bir daqiqa, ma’lumotlarni tekshiryapman."],["22","Rezervasyonunuzu hemen yapabiliriz.","Broningizni darhol amalga oshirishimiz mumkin."],["23","Pasaport bilgilerinizi alabilir miyim?","Pasport ma’lumotlaringizni olsam bo‘ladimi?"],["24","Ödeme işlemini nasıl yapmak istersiniz?","To‘lovni qanday amalga oshirmoqchisiz?"],["25","Rezervasyonunuzu onaylayalım.","Broningizni tasdiqlaylik."],["26","Rezervasyonunuz başarıyla oluşturuldu.","Broningiz muvaffaqiyatli amalga oshirildi."],["27","Rezervasyon bilgilerini size göndereceğim.","Bron ma’lumotlarini sizga yuboraman."],["28","Herhangi bir sorunuz olursa bize ulaşabilirsiniz.","Biror savolingiz bo‘lsa, biz bilan bog‘lanishingiz mumkin."],["29","Seyahatinizle ilgili tüm bilgileri size açıklayacağım.","Sayohatingizga oid barcha ma’lumotlarni tushuntirib beraman."],["30","Size iyi yolculuklar dilerim.","Sizga yaxshi safar tilayman."]],"dialogs":[{"title":"DİYALOG 1 — MÜŞTERİYİ KARŞILAMA VE İHTİYAÇLARINI ÖĞRENME","lines":["Acente çalışanı: Seyahat acentemize hoş geldiniz. Size nasıl yardımcı olabilirim?","Müşteri: Teşekkür ederim. Ailemle birlikte tatil yapmak istiyoruz.","Acente çalışanı: Tabii. Nasıl bir tatil düşünüyorsunuz?","Müşteri: Deniz kenarında, sakin bir yerde tatil yapmak istiyoruz.","Acente çalışanı: Anladım. Kaç kişi seyahat edeceksiniz?","Müşteri: Dört kişiyiz. İki yetişkin ve iki çocuk.","Acente çalışanı: Ne zaman seyahat etmek istiyorsunuz?","Müşteri: Temmuz ayında gitmek istiyoruz.","Acente çalışanı: Kaç gün kalmayı düşünüyorsunuz?","Müşteri: Yaklaşık yedi gün.","Acente çalışanı: Bütçeniz yaklaşık ne kadar?","Müşteri: Çok pahalı olmayan, ama kaliteli bir otel istiyoruz.","Acente çalışanı: Anladım. Size birkaç uygun otel ve paket tur seçeneği sunabilirim.","Müşteri: Çok iyi olur. Özellikle çocuklar için uygun bir otel olursa daha iyi olur.","Acente çalışanı: Elbette. Çocuk aktiviteleri ve aile odaları bulunan otellere bakacağım."]},{"title":"DİYALOG 2 — TUR VE OTEL SEÇENEĞİ SUNMA","lines":["Müşteri: Bu otel hakkında biraz daha bilgi verebilir misiniz?","Acente çalışanı: Tabii. Otel denize oldukça yakın. Ayrıca kahvaltı ve havuz hizmeti fiyata dahil.","Müşteri: Transfer de dahil mi?","Acente çalışanı: Evet, havalimanından otele transfer fiyata dahil.","Müşteri: Peki, uçak bileti dahil mi?","Acente çalışanı: Hayır, uçak bileti paket fiyatına dahil değil.","Müşteri: Otelin kaç yıldızlı olduğunu biliyor musunuz?","Acente çalışanı: Evet, dört yıldızlı bir otel.","Müşteri: Odalar nasıl?","Acente çalışanı: Standart ve aile odaları var. Aileniz için aile odasını tavsiye ederim.","Müşteri: Fiyatı ne kadar?","Acente çalışanı: Yedi gece için toplam fiyat 1.200 avro.","Müşteri: Biraz pahalı olabilir.","Acente çalışanı: İsterseniz size daha uygun fiyatlı iki farklı seçenek daha gösterebilirim.","Müşteri: Evet, lütfen."]},{"title":"DİYALOG 3 — MÜSAİTLİK OLMAYAN TARİH","lines":["Müşteri: Ağustos ayının ilk haftası için otel rezervasyonu yapmak istiyorum.","Acente çalışanı: Tabii. Kaç kişi olacaksınız?","Müşteri: İki kişi.","Acente çalışanı: Bir dakika, müsaitliği kontrol ediyorum.","Müşteri: Tamam.","Acente çalışanı: Maalesef istediğiniz tarihlerde bu otelde müsait oda bulunmuyor.","Müşteri: Hiç mi boş oda yok?","Acente çalışanı: Maalesef yok. Ancak aynı bölgede başka bir otelde müsait odamız var.","Müşteri: O otel nasıl?","Acente çalışanı: Dört yıldızlı ve plaja yaklaşık beş dakika uzaklıkta.","Müşteri: Fiyatı ilk otelden daha mı pahalı?","Acente çalışanı: Hayır, hatta biraz daha uygun.","Müşteri: O zaman ona bakalım.","Acente çalışanı: Tabii. Size otelin fotoğraflarını ve fiyat bilgisini göstereyim.","Müşteri: Çok teşekkür ederim.","Acente çalışanı: Rica ederim. Size en uygun seçeneği bulmaya çalışacağım."]},{"title":"DİYALOG 4 — REZERVASYON BİLGİLERİNDE HATA","lines":["Müşteri: Merhaba. Rezervasyon bilgilerimi kontrol etmek istiyorum.","Acente çalışanı: Tabii. Rezervasyon numaranızı alabilir miyim?","Müşteri: Evet, 45872.","Acente çalışanı: Bir dakika kontrol ediyorum.","Müşteri: Tamam.","Acente çalışanı: Rezervasyonunuzu buldum. İki kişi, beş gece, doğru mu?","Müşteri: Evet. Ama giriş tarihi yanlış görünüyor.","Acente çalışanı: Haklısınız. Sistemimizde giriş tarihi bir gün farklı kaydedilmiş.","Müşteri: Ben özellikle 15 Ağustos için rezervasyon yapmıştım.","Acente çalışanı: Özür dilerim. Hemen kontrol edip düzelteceğim.","Müşteri: Bu değişiklik için ekstra ücret ödemem gerekiyor mu?","Acente çalışanı: Hayır, bu bizim sistemimizden kaynaklanan bir hata. Ekstra ücret alınmayacak.","Müşteri: Tamam, teşekkür ederim.","Acente çalışanı: Rica ederim. Değişikliği yaptıktan sonra size yeni rezervasyon belgesini göndereceğim."]}],"grammar":["GRAMER — GEREKLİ TÜRKÇE","5.1. “-MAK / -MEK İSTEMEK” — XOHLASH","Turk tilida biror ishni qilish istagini bildirish uchun -mak / -mek istemek ishlatiladi.","Örnekler:","Seyahat etmek istiyorum.\n— Sayohat qilmoqchiman.","Otel rezervasyonu yapmak istiyorum.\n— Mehmonxona bron qilmoqchiman.","Antalya'ya gitmek istiyoruz.\n— Antaliyaga bormoqchimiz.","Bu otelde kalmak istiyorum.\n— Shu mehmonxonada qolmoqchiman.","5.2. “-EBİLMEK / -ABİLMEK” — IMKONIYAT VA MULoyim SO‘ROV","Bu shakl “qila olmoq”, shuningdek muloyim so‘rov ma’nosida ishlatiladi.","Örnekler:","Size birkaç seçenek sunabilirim.\n— Sizga bir nechta variant taklif qila olaman.","Fiyatları kontrol edebilir misiniz?\n— Narxlarni tekshira olasizmi?","Rezervasyon yapabilir miyim?\n— Bron qilsam bo‘ladimi?","Size yardımcı olabilir miyim?\n— Sizga yordam bera olamanmi?","5.3. “-DA / -DE” — JOY VA VAQT","-da / -de qo‘shimchasi joy yoki vaqtni bildirish uchun ishlatiladi.","Örnekler:","Otelde müsait oda var.\n— Mehmonxonada bo‘sh xona bor.","Ağustos ayında seyahat edeceğiz.\n— Avgust oyida sayohat qilamiz.","İstanbul'da üç gün kalacağız.\n— Istanbulda uch kun qolamiz.","Bu tarihte müsaitlik yok.\n— Bu sanada bo‘sh joy yo‘q.","5.4. “İÇİN” — UCHUN","İçin — “uchun” degani. Turizmda maqsadni yoki kim uchun ekanini bildirishda ko‘p ishlatiladi.","Örnekler:","Aileniz için uygun bir otel bulabilirim.\n— Oilangiz uchun mos mehmonxona topa olaman.","Bu paket sizin için uygun.\n— Bu paket siz uchun mos.","Çocuklar için özel aktiviteler var.\n— Bolalar uchun maxsus mashg‘ulotlar bor.","Seyahatiniz için gerekli bilgileri hazırladım.\n— Sayohatingiz uchun kerakli ma’lumotlarni tayyorladim.","5.5. “DAHİL / HARİÇ” — KIRITILGAN / KIRITILMAGAN","Turizm sohasida narx tarkibini tushuntirish uchun bu ikki so‘z juda muhim.","Dahil — kiritilgan.\nHariç — kiritilmagan.","Örnekler:","Kahvaltı fiyata dahil.\n— Nonushta narxga kiritilgan.","Transfer fiyata dahil.\n— Transfer narxga kiritilgan.","Uçak bileti fiyata dahil değil.\n— Samolyot chiptasi narxga kiritilmagan.","Vergiler fiyata hariç.\n— Soliqlar narxga kiritilmagan."],"video":"https://youtu.be/rcp8xyHsRcM?si=dJcZLZpTfrnGQQSt","document":"assets/materials/day4.docx"},{"day":5,"title":"GİRİŞ","subtitle":"Tur operatörleri, seyahat acenteleri, oteller, transfer şirketleri, rehberler ve diğer turizm işletmeleri arasında güçlü bir iletişim olması, hizmet kalitesinin devamlılığı açısından büyük önem taşır.","words":[["1","Tur operatörü","Tur operatori"],["2","İş ortağı","Hamkor"],["3","Acente","Agentlik"],["4","Kontenjan","Ajratilgan joy / kvota"],["5","Grup","Guruh"],["6","Grup rezervasyonu","Guruh bron qilinishi"],["7","Oda kontenjanı","Xona kvotasi"],["8","Araç","Transport vositasi"],["9","Şoför","Haydovchi"],["10","Rehber","Gid / yo‘riqchi"],["11","Tur programı","Tur dasturi"],["12","Güzergâh","Yo‘nalish"],["13","Konaklama","Joylashish / tunash"],["14","Kontrat","Shartnoma"],["15","Anlaşma","Kelishuv"],["16","Fiyat teklifi","Narx taklifi"],["17","Teklif","Taklif"],["18","Teyit","Tasdiq"],["19","Onay","Ma’qullash / tasdiqlash"],["20","Değişiklik","O‘zgarish"],["21","İptal","Bekor qilish"],["22","Ek ücret","Qo‘shimcha to‘lov"],["23","Özel talep","Maxsus talab"],["24","Müsaitlik","Bo‘sh joy / mavjudlik"],["25","Fatura","Hisob-faktura"],["26","Ödeme koşulları","To‘lov shartlari"],["27","Tarih","Sana"],["28","Varış","Yetib kelish"],["29","Kalkış","Jo‘nab ketish"],["30","Bilgi","Ma’lumot"]],"phrases":[["1","İş birliğiniz için teşekkür ederiz.","Hamkorligingiz uchun rahmat."],["2","Yeni bir grup için bilgi almak istiyorum.","Yangi guruh uchun ma’lumot olmoqchiman."],["3","Bu tarihler için müsaitliğiniz var mı?","Bu sanalar uchun bo‘sh joyingiz bormi?"],["4","Grup için kaç oda ayırabilirsiniz?","Guruh uchun nechta xona ajrata olasiz?"],["5","Tek kişilik oda fiyatını öğrenebilir miyim?","Bir kishilik xona narxini bilsam bo‘ladimi?"],["6","Grup fiyatınız nedir?","Guruh narxingiz qancha?"],["7","Fiyat teklifinizi gönderebilir misiniz?","Narx taklifingizni yubora olasizmi?"],["8","Teklifi e-posta ile göndereceğim.","Taklifni elektron pochta orqali yuboraman."],["9","Rezervasyonu teyit etmek istiyoruz.","Bronni tasdiqlamoqchimiz."],["10","Rezervasyonumuz kesinleşti.","Bronimiz aniq tasdiqlandi."],["11","Oda sayısında değişiklik oldu.","Xonalar sonida o‘zgarish bo‘ldi."],["12","Bir odam daha eklendi.","Yana bir kishi qo‘shildi."],["13","Bir odam rezervasyondan çıktı.","Bir kishi bronidan chiqdi."],["14","Giriş tarihini değiştirmemiz gerekiyor.","Kirish sanasini o‘zgartirishimiz kerak."],["15","Çıkış tarihini bir gün uzatmak istiyoruz.","Chiqish sanasini bir kunga uzaytirmoqchimiz."],["16","Ek ücret var mı?","Qo‘shimcha to‘lov bormi?"],["17","Bu hizmet fiyata dahil mi?","Bu xizmat narxga kiritilganmi?"],["18","Transfer fiyatını da öğrenmek istiyorum.","Transfer narxini ham bilmoqchiman."],["19","Araç kapasitesi kaç kişi?","Transport vositasi nechta kishilik?"],["20","Grup için büyük bir araç gerekiyor.","Guruh uchun katta transport kerak."],["21","Rehber bilgilerini paylaşabilir misiniz?","Gid ma’lumotlarini yubora olasizmi?"],["22","Programda küçük bir değişiklik yaptık.","Dasturda kichik o‘zgarish qildik."],["23","Misafirlerin özel bir talebi var.","Mehmonlarning maxsus talabi bor."],["24","Bu talebi karşılayabilir misiniz?","Bu talabni bajara olasizmi?"],["25","Lütfen müsaitliği tekrar kontrol edin.","Iltimos, mavjud joyni yana tekshiring."],["26","Onayınızı bekliyoruz.","Tasdig‘ingizni kutyapmiz."],["27","Bilgileri bugün paylaşacağım.","Ma’lumotlarni bugun yuboraman."],["28","Herhangi bir değişiklik olursa sizi bilgilendireceğim.","Biror o‘zgarish bo‘lsa, sizga xabar beraman."],["29","Konuyu ilgili departmana ileteceğim.","Masalani tegishli bo‘limga yetkazaman."],["30","İş birliğimizin devamını diliyoruz.","Hamkorligimiz davom etishini tilaymiz."]],"dialogs":[{"title":"DİYALOG 1 — YENİ BİR GRUP İÇİN OTEL KONTENJANI","lines":["Acente: Merhaba, iyi günler. Yeni bir grubumuz için otel kontenjanı hakkında bilgi almak istiyorum.","Otel Yetkilisi: Merhaba, tabii. Grup kaç kişiden oluşuyor?","Acente: Toplam 24 kişi. Grup 10 Haziran'da giriş yapacak ve 14 Haziran'da çıkış yapacak.","Otel Yetkilisi: Toplam dört gece, doğru mu?","Acente: Evet, doğru. On iki çift kişilik oda ve birkaç tek kişilik oda gerekiyor.","Otel Yetkilisi: Bu tarihler için standart odalarımızda müsaitlik var. Ancak tek kişilik odaların sayısı sınırlı.","Acente: Kaç tane tek kişilik oda ayırabilirsiniz?","Otel Yetkilisi: Dört tek kişilik oda ayırabiliriz.","Acente: Tamam. Fiyat teklifini ve oda şartlarını bize gönderebilir misiniz?","Otel Yetkilisi: Elbette. Teklifi bugün e-posta ile göndereceğim.","Acente: Çok teşekkür ederim. Teklifi aldıktan sonra grup rezervasyonunu kesinleştireceğiz.","Otel Yetkilisi: Rica ederim. Herhangi bir sorunuz olursa bize ulaşabilirsiniz."]},{"title":"DİYALOG 2 — FİYAT TEKLİFİ VE ÖZEL TALEP","lines":["Tur Operatörü: Merhaba, geçen hafta gönderdiğiniz fiyat teklifini inceledik.","Otel Yetkilisi: Merhaba. Umarım teklif sizin için uygundur.","Tur Operatörü: Genel olarak uygun. Ancak grubumuzda iki yaşlı misafir var. Onlar için asansöre yakın oda talep ediyoruz.","Otel Yetkilisi: Tabii. Bu talebi rezervasyon notlarına ekleyebiliriz.","Tur Operatörü: Ayrıca kahvaltının saatini de öğrenmek istiyorum.","Otel Yetkilisi: Kahvaltımız sabah 07.00'de başlıyor ve 10.00'a kadar devam ediyor.","Tur Operatörü: Çok iyi. Bir de grup için özel bir akşam yemeği organize edebilir misiniz?","Otel Yetkilisi: Evet, restoranımız grup yemekleri için hizmet veriyor. Menü seçeneklerini de size gönderebiliriz.","Tur Operatörü: Harika. O zaman menü seçeneklerini ve grup fiyatını da teklifinize ekleyebilir misiniz?","Otel Yetkilisi: Elbette. Güncellenmiş teklifi yarın sabah göndereceğim.","Tur Operatörü: Teşekkür ederim. Teklifi müşterimize sunacağız."]},{"title":"DİYALOG 3 — REZERVASYONDA DEĞİŞİKLİK","lines":["Acente: Merhaba, 18 Temmuz tarihli grup rezervasyonumuzla ilgili arıyorum.","Otel Yetkilisi: Merhaba, buyurun. Rezervasyon numaranızı alabilir miyim?","Acente: Tabii, rezervasyon numaramız TR4587.","Otel Yetkilisi: Evet, rezervasyonu görüyorum. Nasıl yardımcı olabilirim?","Acente: Grubumuzda iki kişi daha eklendi. Bu nedenle oda sayısını artırmamız gerekiyor.","Otel Yetkilisi: Şu anda iki standart odamız daha mevcut.","Acente: Çok iyi. Bu iki odayı aynı grup rezervasyonuna ekleyebilir misiniz?","Otel Yetkilisi: Evet, ekleyebiliriz. Ancak toplam fiyat değişecektir.","Acente: Sorun değil. Güncellenmiş toplam fiyatı bize gönderebilir misiniz?","Otel Yetkilisi: Tabii. Yeni fiyatı ve güncellenmiş rezervasyon belgesini bugün göndereceğim.","Acente: Çok teşekkür ederim. Ayrıca misafir listesini de güncelleyeceğiz.","Otel Yetkilisi: Tamamdır. Güncel listeyi aldığımızda rezervasyonu tekrar kontrol ederiz."]},{"title":"DİYALOG 4 — ARAÇ VE TRANSFER SORUNU","lines":["Acente: Merhaba. Yarın havaalanından otele yapılacak grup transferiyle ilgili arıyorum.","Transfer Şirketi: Merhaba. Buyurun.","Acente: Grubumuz 32 kişi. Ancak bize gönderilen araç bilgisi 25 kişilik görünüyor.","Transfer Şirketi: Bir dakika, sistemi kontrol edeyim. Evet, burada yanlışlıkla 25 kişilik araç seçilmiş.","Acente: Grup 32 kişi olduğu için daha büyük bir araç gerekiyor.","Transfer Şirketi: Haklısınız. Hemen değişiklik yapıyorum.","Acente: Yeni araç bilgilerini ne zaman gönderebilirsiniz?","Transfer Şirketi: En geç bir saat içinde araç ve şoför bilgilerini size göndereceğim.","Acente: Çok iyi. Lütfen uçuş saatini de dikkate alın. Uçuş 16.30'da varıyor.","Transfer Şirketi: Tamam. Şoför, uçuş saatinden sonra havaalanında bekleyecek.","Acente: Teşekkür ederim. Misafirlerin herhangi bir sorun yaşamamasını istiyoruz.","Transfer Şirketi: Merak etmeyin. Transferi tekrar kontrol edeceğim."]}],"grammar":["5. GRAMER — TUR OPERATÖRÜ VE İŞ ORTAKLARIYLA İLETİŞİM","Bu bölümde daha önceki konularda kullanılan temel dil bilgisi yapılarını tekrar etmek yerine, iş ortaklarıyla profesyonel iletişimde sık kullanılan yeni yapıları öğrenelim.","5.1. “-DI / -Dİ / -DU / -DÜ” — GEÇMİŞ ZAMAN","Bu ek, geçmişte tamamlanmış işleri anlatmak için kullanılır.","Örnekler:","Rezervasyonu kontrol ettim.\n— Bronni tekshirdim.","Otelle görüştük.\n— Mehmonxona bilan gaplashdik.","Fiyat teklifini gönderdim.\n— Narx taklifini yubordim.","Müşteri rezervasyonu onayladı.\n— Mijoz bronni tasdiqladi.","Araç bilgilerini aldık.\n— Transport ma’lumotlarini oldik.","5.2. “-ECEK / -ACAK” — GELECEK ZAMAN","Kelajakda amalga oshiriladigan ishlar uchun ishlatiladi.","Örnekler:","Teklifi bugün göndereceğim.\n— Taklifni bugun yuboraman.","Yarın otelle görüşeceğiz.\n— Ertaga mehmonxona bilan gaplashamiz.","Misafir listesini akşam paylaşacağım.\n— Mehmonlar ro‘yxatini kechqurun yuboraman.","Grup yarın İstanbul'a gelecek.\n— Guruh ertaga Istanbulga keladi.","Güncellenmiş programı size göndereceğiz.\n— Yangilangan dasturni sizga yuboramiz.","5.3. “-SA / -SE” — SHART","Bu yapı bir durumun başka bir duruma bağlı olduğunu anlatır. Turizm sektöründe alternatif ve çözüm sunarken çok kullanılır.","Örnekler:","Müsaitlik varsa rezervasyonu hemen yapabiliriz.\n— Agar bo‘sh joy bo‘lsa, bronni darhol qila olamiz.","Oda uygun olursa gruba ayırabiliriz.\n— Agar xona mos bo‘lsa, guruh uchun ajratamiz.","Misafir erken gelirse resepsiyona bilgi verin.\n— Agar mehmon erta kelsa, resepsiyaga xabar bering.","Fiyat uygunsa rezervasyonu kesinleştirebiliriz.\n— Agar narx mos bo‘lsa, bronni aniq tasdiqlashimiz mumkin.","Araç bulunmazsa başka bir şirketle görüşeceğiz.\n— Agar transport topilmasa, boshqa kompaniya bilan gaplashamiz.","5.4. “-A KADAR” — ...GACHA","Bir ish yoki vaqtning chegarasini bildirir.","Örnekler:","Saat 18.00'e kadar size bilgi vereceğim.\n— Soat 18:00 gacha sizga ma’lumot beraman.","Rezervasyonu yarına kadar kesinleştirmemiz gerekiyor.\n— Bronni ertagacha aniq tasdiqlashimiz kerak.","Misafirler akşama kadar otelde kalacak.\n— Mehmonlar kechgacha mehmonxonada qoladilar.","Fiyat teklifini öğlene kadar gönderebilir misiniz?\n— Narx taklifini tushgacha yubora olasizmi?","5.5. “-DAN İTİBAREN” — ...DAN BOSHLAB","Bu yapı bir işin veya durumun hangi zamandan başladığını belirtir.","Örnekler:","1 Haziran'dan itibaren yeni fiyatlar geçerli olacak.\n— 1-iyundan boshlab yangi narxlar amal qiladi.","Pazartesiden itibaren grup rezervasyonlarını kabul edeceğiz.\n— Dushanbadan boshlab guruh bronlarini qabul qilamiz.","Saat 10.00'dan itibaren transfer hizmeti başlayacak.\n— Soat 10:00 dan boshlab transfer xizmati boshlanadi.","Gelecek aydan itibaren yeni program uygulanacak.\n— Keyingi oydan boshlab yangi dastur qo‘llaniladi."],"video":"https://youtu.be/_FD4Wz3mG-I?si=6N9e_VKCBdG0hKXX","document":"assets/materials/day5.docx"},{"day":6,"title":"GİRİŞ","subtitle":"Tur satışında başarılı olmak yalnızca tur hakkında bilgi vermekle sınırlı değildir. Turizm çalışanı müşterinin beklentisini doğru anlamalı, bütçesini ve seyahat amacını öğrenmeli, uygun seçenekleri sunmalı ve müşterinin karar vermesine yardımcı olmalıdır.","words":[["1","Tur satışı","Tur sotish"],["2","Müşteri","Mijoz"],["3","Danışmanlık","Maslahat berish"],["4","Tur","Tur"],["5","Paket","Paket"],["6","Tur programı","Tur dasturi"],["7","Gezi","Sayohat / ekskursiya"],["8","Tatil","Ta’til"],["9","Destinasyon","Sayohat manzili"],["10","Bütçe","Byudjet"],["11","Seçenek","Variant"],["12","Tercih","Tanlov / afzallik"],["13","Avantaj","Afzallik"],["14","Dezavantaj","Kamchilik"],["15","Dahil","Kiritilgan"],["16","Hariç","Kiritilmagan"],["17","Ücret","To‘lov / narx"],["18","Kampanya","Aksiya"],["19","İndirim","Chegirma"],["20","Fırsat","Imkoniyat / foydali taklif"],["21","Rezervasyon","Bron"],["22","Ödeme","To‘lov"],["23","Kapora","Avans"],["24","İptal koşulu","Bekor qilish sharti"],["25","Değişiklik","O‘zgarish"],["26","Seyahat tarihi","Sayohat sanasi"],["27","Konaklama","Joylashish"],["28","Ulaşım","Transport"],["29","Rehberlik hizmeti","Gid xizmati"],["30","Müşteri memnuniyeti","Mijoz mamnunligi"]],"phrases":[["1","Nasıl bir tatil düşünüyorsunuz?","Qanday ta’tilni rejalashtiryapsiz?"],["2","Seyahatinizin amacı nedir?","Sayohatingizdan maqsad nima?"],["3","Kaç gün tatil yapmak istiyorsunuz?","Necha kun dam olishni xohlaysiz?"],["4","Bütçeniz için uygun seçeneklerimiz var.","Byudjetingizga mos variantlarimiz bor."],["5","Size birkaç alternatif gösterebilirim.","Sizga bir nechta muqobil variant ko‘rsatishim mumkin."],["6","Bu tur özellikle aileler için uygundur.","Bu tur ayniqsa oilalar uchun mos."],["7","Bu paket çiftler tarafından çok tercih ediliyor.","Bu paketni juftliklar ko‘p tanlaydi."],["8","Bu turun programı oldukça yoğun.","Bu turning dasturi ancha tig‘iz."],["9","Daha sakin bir programımız da var.","Bizda sokinroq dastur ham bor."],["10","Bu seçeneğin fiyatı daha uygun.","Bu variantning narxi qulayroq."],["11","Bu paketin oteli daha kaliteli.","Bu paketdagi mehmonxona sifati yaxshiroq."],["12","Fiyata ulaşım dahildir.","Narxga transport kiritilgan."],["13","Rehberlik hizmeti de pakete dahildir.","Gid xizmati ham paketga kiritilgan."],["14","Öğle yemeği fiyata dahil değildir.","Tushlik narxga kiritilmagan."],["15","Bu turda boş zamanınız daha fazla olacak.","Bu turda bo‘sh vaqtingiz ko‘proq bo‘ladi."],["16","Programı size ayrıntılı olarak açıklayayım.","Dasturni sizga batafsil tushuntirib beray."],["17","Önce tur programına bakalım.","Avval tur dasturini ko‘rib chiqaylik."],["18","Otel hakkında da bilgi verebilirim.","Mehmonxona haqida ham ma’lumot bera olaman."],["19","İsterseniz daha ekonomik bir seçenek sunabilirim.","Xohlasangiz, tejamkorroq variant taklif qila olaman."],["20","İsterseniz daha konforlu bir paket seçebiliriz.","Xohlasangiz, qulayroq paket tanlashimiz mumkin."],["21","Bu kampanya sınırlı bir süre için geçerli.","Bu aksiya cheklangan vaqt uchun amal qiladi."],["22","Bu fiyat kişi başı hesaplanmıştır.","Bu narx bir kishi uchun hisoblangan."],["23","Çocuklar için farklı bir ücret uygulanıyor.","Bolalar uchun boshqa narx qo‘llaniladi."],["24","İptal koşullarını size açıklayayım.","Bekor qilish shartlarini sizga tushuntirib beray."],["25","Rezervasyon için küçük bir kapora gerekiyor.","Bron uchun kichik avans kerak."],["26","Ödeme seçeneklerini size gösterebilirim.","To‘lov variantlarini sizga ko‘rsatishim mumkin."],["27","Karar vermeden önce tüm seçenekleri inceleyebilirsiniz.","Qaror qilishdan oldin barcha variantlarni ko‘rib chiqishingiz mumkin."],["28","Sizin için en uygun seçeneği birlikte bulabiliriz.","Siz uchun eng mos variantni birgalikda topishimiz mumkin."],["29","Başka bir sorunuz varsa memnuniyetle cevaplarım.","Boshqa savolingiz bo‘lsa, mamnuniyat bilan javob beraman."],["30","Rezervasyonunuzu bugün tamamlayabiliriz.","Bronni bugun yakunlashimiz mumkin."]],"dialogs":[{"title":"DİYALOG 1 — AİLE İÇİN UYGUN TUR SEÇME","lines":["Müşteri: Merhaba. Ailemle birlikte yaz tatili yapmak istiyoruz. Bize uygun bir tur arıyoruz.","Danışman: Merhaba, memnuniyetle yardımcı olurum. Kaç kişi seyahat edeceksiniz?","Müşteri: İki yetişkin ve iki çocuk olacağız.","Danışman: Anladım. Çocukların yaşları kaç?","Müşteri: Biri altı, diğeri on yaşında.","Danışman: O zaman aileler için uygun olan birkaç paketimiz var. Deniz tatili mi düşünüyorsunuz, yoksa geziler de olsun mu?","Müşteri: Hem deniz tatili yapmak hem de birkaç tarihi yer görmek istiyoruz.","Danışman: O zaman size karma bir program önerebilirim. İlk günlerde otelde dinlenebilirsiniz. Daha sonra şehir turu ve tarihi yer gezileri var.","Müşteri: Program çocuklar için çok yorucu olur mu?","Danışman: Hayır. Program oldukça dengeli. Ayrıca çocuklar için boş zaman da bulunuyor.","Müşteri: Fiyat konusunda da bilgi verebilir misiniz?","Danışman: Tabii. İki farklı paketimiz var. Birincisi daha ekonomik, ikincisinde ise daha kaliteli bir otel bulunuyor.","Müşteri: Önce iki seçeneğin de detaylarını görmek istiyorum.","Danışman: Elbette. Programları ve fiyatları birlikte inceleyebiliriz."]},{"title":"DİYALOG 2 — MÜŞTERİ DAHA UCUZ SEÇENEK İSTİYOR","lines":["Müşteri: Bu turun fiyatı biraz yüksek. Daha ekonomik bir seçeneğiniz var mı?","Danışman: Evet, aynı bölge için daha uygun fiyatlı başka bir paketimiz var.","Müşteri: Aralarında ne fark var?","Danışman: İlk pakette dört yıldızlı otel bulunuyor. İkinci pakette ise üç yıldızlı bir otel var.","Müşteri: Ulaşım iki pakette de dahil mi?","Danışman: Evet, ulaşım her iki pakette de dahil. Ancak ikinci pakette bazı geziler fiyata dahil değil.","Müşteri: Otel merkeze uzak mı?","Danışman: Hayır, merkeze yaklaşık on beş dakika uzaklıkta.","Müşteri: Kahvaltı var mı?","Danışman: Evet, kahvaltı dahil.","Müşteri: O zaman ikinci paket benim bütçeme daha uygun.","Danışman: İsterseniz bu paketin programını da ayrıntılı şekilde açıklayayım.","Müşteri: Evet, lütfen.","Danışman: Tabii. Öncelikle ulaşım ve konaklama hizmetlerini anlatayım, daha sonra geziler hakkında bilgi vereyim."]},{"title":"DİYALOG 3 — MÜŞTERİ KARAR VEREMİYOR","lines":["Müşteri: İki paket arasında kaldım. Hangisini seçmem gerektiğine karar veremiyorum.","Danışman: Tabii, size yardımcı olayım. Öncelikle sizin için en önemli konu nedir?","Müşteri: Otelin iyi olması ve çok fazla yorulmamak istiyorum.","Danışman: O zaman ikinci paket sizin için daha uygun olabilir. Bu paketin oteli daha konforlu ve programı daha sakin.","Müşteri: Ama fiyatı biraz daha yüksek.","Danışman: Evet, fiyat farkı var. Ancak bu pakette daha kaliteli bir otel ve daha fazla serbest zaman bulunuyor.","Müşteri: İlk pakette program nasıl?","Danışman: İlk paket daha yoğun. Daha fazla yer görebilirsiniz, fakat gün içinde daha az boş zamanınız olur.","Müşteri: Ben dinlenmek istiyorum. Çok fazla gezmek istemiyorum.","Danışman: O zaman ikinci seçeneği tavsiye ederim.","Müşteri: Mantıklı. Peki, bu pakette rehberlik hizmeti var mı?","Danışman: Evet, şehir turlarında profesyonel rehber hizmeti bulunuyor.","Müşteri: Tamam. O zaman ikinci paketi seçmek istiyorum.","Danışman: Çok iyi bir seçim. Şimdi rezervasyon için gerekli bilgileri alabilirim."]},{"title":"DİYALOG 4 — MÜŞTERİ TUR PROGRAMINDAN MEMNUN DEĞİL","lines":["Müşteri: Programı inceledim ama bazı noktaları değiştirmek istiyorum.","Danışman: Tabii. Hangi bölüm sizin için uygun değil?","Müşteri: İlk gün çok fazla gezi var. Sabah erken başlayıp akşama kadar devam ediyor.","Danışman: Anlıyorum. İlk günün programı gerçekten yoğun.","Müşteri: Sabah biraz daha geç başlamak mümkün mü?","Danışman: Grup programına bağlı olarak bazı saatleri değiştirebiliriz.","Müşteri: Ayrıca öğleden sonra biraz boş zamanımız olsun istiyorum.","Danışman: Bu durumda programı daha dengeli hale getirebiliriz.","Müşteri: Çok iyi olur.","Danışman: İlk geziyi biraz kısaltıp öğleden sonra iki saat serbest zaman bırakabiliriz.","Müşteri: Bu şekilde program benim için daha uygun.","Danışman: Tamam. Değiştirilmiş programı hazırlayıp size göstereceğim.","Müşteri: Teşekkür ederim. Böylece turu satın almaya daha rahat karar verebilirim."]}],"grammar":["5. GRAMER — TUR SATIŞINDA KULLANILAN YENİ YAPILAR","Bu bölümde müşteriye seçenek sunarken, karşılaştırma yaparken ve tavsiyede bulunurken kullanılan yeni dil bilgisi yapılarını öğrenelim.","5.1. “-DAN DAHA” — ...DAN KO‘RA / ...DAN YAXSHIROQ","İki seçeneği karşılaştırmak için kullanılır.","Örnekler:","Bu otel diğer otelden daha konforlu.\n— Bu mehmonxona boshqa mehmonxonadan ko‘ra qulayroq.","Bu paket diğerinden daha ekonomik.\n— Bu paket boshqasidan tejamkorroq.","Bu tur şehir turundan daha sakin.\n— Bu tur shahar turidan ko‘ra sokinroq.","İkinci seçenek birinciden daha uygun.\n— Ikkinchi variant birinchisidan mosroq.","5.2. “EN” — ENG","Bir guruh ichidagi eng yuqori darajani bildirish uchun ishlatiladi.","Örnekler:","Bu bizim en popüler turumuz.\n— Bu bizning eng mashhur turimiz.","Bu aileler için en uygun paket.\n— Bu oilalar uchun eng mos paket.","En çok tercih edilen otelimiz budur.\n— Eng ko‘p tanlanadigan mehmonxonamiz shu.","Bu ayın en uygun fiyatlı turudur.\n— Bu oyning eng qulay narxli turidir.","5.3. “İÇİN” — MAQSAD VA KIM UCHUN","Bu yapı bir şeyin kim için veya ne amaçla olduğunu anlatır.","Örnekler:","Bu tur aileler için uygundur.\n— Bu tur oilalar uchun mos.","Bu paket çocuklu aileler için hazırlanmıştır.\n— Bu paket bolali oilalar uchun tayyorlangan.","Dinlenmek için bu oteli tavsiye ederim.\n— Dam olish uchun bu mehmonxonani tavsiya qilaman.","Şehir gezisi için ayrı bir programımız var.\n— Shahar sayohati uchun alohida dasturimiz bor.","5.4. “GEREK / GEREKMEK” — KERAK / ZARUR BO‘LISH","Mijozga kerakli ma’lumot yoki harakatni tushuntirishda ishlatiladi.","Örnekler:","Rezervasyon için pasaport bilgileri gerek.\n— Bron uchun pasport ma’lumotlari kerak.","Bu tur için önceden rezervasyon yapmak gerekiyor.\n— Bu tur uchun oldindan bron qilish kerak.","Ödeme sırasında kimlik göstermek gerekiyor.\n— To‘lov vaqtida shaxsni tasdiqlovchi hujjat ko‘rsatish kerak.","Tur başlamadan önce buluşma noktasını öğrenmek gerek.\n— Tur boshlanishidan oldin uchrashuv joyini bilish kerak.","5.5. “YERİNE” — O‘RNIGA","Bir variantni boshqa variant bilan almashtirishni bildiradi.","Örnekler:","Bu otel yerine başka bir otel seçebiliriz.\n— Bu mehmonxona o‘rniga boshqa mehmonxona tanlashimiz mumkin.","Şehir turu yerine serbest zaman tercih edebilirsiniz.\n— Shahar turining o‘rniga bo‘sh vaqtni tanlashingiz mumkin.","Bu paket yerine daha ekonomik bir paket sunabilirim.\n— Bu paket o‘rniga tejamkorroq paket taklif qilishim mumkin.","Öğle yemeği yerine serbest zamanınız olabilir.\n— Tushlik o‘rniga bo‘sh vaqtingiz bo‘lishi mumkin."],"video":"https://youtu.be/gSTrbC21OjY?si=ug92NEeWb-H4-PUf","document":"assets/materials/day6.docx"},{"day":7,"title":"3.1. TUR REHBERLERİ İÇİN TÜRKÇE","subtitle":"GİRİŞ","words":[["1","Tur rehberi","Tur gid"],["2","Turist","Sayyoh"],["3","Grup","Guruh"],["4","Gezi","Ekskursiya / sayohat"],["5","Tur","Tur"],["6","Güzergâh","Yo‘nalish"],["7","Tarihi yer","Tarixiy joy"],["8","Müze","Muzey"],["9","Anıt","Yodgorlik"],["10","Saray","Saroy"],["11","Cami","Masjid"],["12","Kilise","Cherkov"],["13","Meydan","Maydon"],["14","Sokak","Ko‘cha"],["15","Bina","Bino"],["16","Tarih","Tarix"],["17","Kültür","Madaniyat"],["18","Gelenek","An’ana"],["19","Eser","Asar / yodgorlik"],["20","Hikâye","Hikoya"],["21","Bilgi","Ma’lumot"],["22","Açıklama","Tushuntirish"],["23","Fotoğraf","Surat"],["24","Buluşma noktası","Uchrashuv joyi"],["25","Giriş","Kirish"],["26","Çıkış","Chiqish"],["27","Bilet","Chipta"],["28","Kalabalık","Gavjum"],["29","Serbest zaman","Bo‘sh vaqt"],["30","Hatıra","Esdalik"]],"phrases":[["1","Hepiniz hoş geldiniz.","Barchangiz xush kelibsiz."],["2","Ben tur rehberinizim.","Men sizning tur gidingizman."],["3","Bugün size eşlik edeceğim.","Bugun sizga hamrohlik qilaman."],["4","Bugünkü turumuza başlayalım.","Bugungi turimizni boshlaylik."],["5","Öncelikle tur programımızı açıklayayım.","Avvalo tur dasturimizni tushuntirib beray."],["6","Bugün birkaç önemli yeri ziyaret edeceğiz.","Bugun bir nechta muhim joylarni ko‘ramiz."],["7","İlk durağımız burası olacak.","Birinchi to‘xtash joyimiz shu yer bo‘ladi."],["8","Burada yaklaşık otuz dakika kalacağız.","Bu yerda taxminan 30 daqiqa qolamiz."],["9","Lütfen grubumuzdan ayrılmayın.","Iltimos, guruhimizdan ajralmang."],["10","Buluşma noktamız burasıdır.","Uchrashuv joyimiz shu yer."],["11","Lütfen saatimize dikkat edin.","Iltimos, vaqtga e’tibor bering."],["12","Birazdan tekrar burada buluşacağız.","Birozdan keyin yana shu yerda uchrashamiz."],["13","Şimdi size bu yer hakkında bilgi vereceğim.","Hozir sizga bu joy haqida ma’lumot beraman."],["14","Bu bina çok önemli bir tarihi eserdir.","Bu bino juda muhim tarixiy yodgorlikdir."],["15","Bu yapının tarihi oldukça eskidir.","Bu inshootning tarixi juda qadimiy."],["16","Bu yerin ilginç bir hikâyesi var.","Bu joyning qiziqarli tarixi bor."],["17","Fotoğraf çekmek için birkaç dakikanız var.","Suratga olish uchun bir necha daqiqangiz bor."],["18","Lütfen fotoğraf çekerken dikkatli olun.","Iltimos, suratga olayotganda ehtiyot bo‘ling."],["19","Sorularınızı memnuniyetle cevaplarım.","Savollaringizga mamnuniyat bilan javob beraman."],["20","Anlamadığınız bir nokta olursa lütfen sorun.","Tushunmagan joyingiz bo‘lsa, iltimos, so‘rang."],["21","Biraz daha yakına geçebilirsiniz.","Biroz yaqinroqqa o‘tishingiz mumkin."],["22","Burada kısa bir mola vereceğiz.","Bu yerda qisqa tanaffus qilamiz."],["23","Şimdi serbest zamanınız başlıyor.","Hozir bo‘sh vaqtingiz boshlanadi."],["24","Serbest zamanın sonunda burada buluşacağız.","Bo‘sh vaqt tugagach, shu yerda uchrashamiz."],["25","Lütfen kişisel eşyalarınıza dikkat edin.","Iltimos, shaxsiy buyumlaringizga e’tibor bering."],["26","Kalabalık nedeniyle biraz yavaş ilerleyeceğiz.","Gavjumlik sababli biroz sekin harakatlanamiz."],["27","Turumuzun bir sonraki durağı müze olacak.","Turimizning keyingi bekati muzey bo‘ladi."],["28","Buradan yürüyerek devam edeceğiz.","Bu yerdan piyoda davom etamiz."],["29","Turumuzun sonunda otele döneceğiz.","Tur oxirida mehmonxonaga qaytamiz."],["30","Katıldığınız için teşekkür ederim.","Qatnashganingiz uchun rahmat."]],"dialogs":[{"title":"DİYALOG 1 — TURUN BAŞLANGICI","lines":["Rehber: Günaydın, hepiniz hoş geldiniz. Ben bugün tur boyunca size eşlik edecek rehberinizim.","Turist: Günaydın.","Rehber: Öncelikle bugünkü programımız hakkında kısa bilgi vermek istiyorum. İlk olarak tarihi meydana gideceğiz. Daha sonra müzeyi ziyaret edeceğiz ve öğle yemeğinden sonra serbest zamanımız olacak.","Turist: Serbest zaman ne kadar sürecek?","Rehber: Yaklaşık bir buçuk saat sürecek.","Turist: Buluşma noktamız neresi olacak?","Rehber: Serbest zamanın sonunda meydanın girişinde tekrar buluşacağız.","Turist: Saat kaçta?","Rehber: Saat 16.30'da burada olmanızı rica ediyorum.","Turist: Tamam.","Rehber: Ayrıca grubumuzdan ayrılmamanızı ve özellikle kalabalık yerlerde kişisel eşyalarınıza dikkat etmenizi rica ediyorum.","Turist: Teşekkür ederiz.","Rehber: Rica ederim. Şimdi turumuza başlayabiliriz."]},{"title":"DİYALOG 2 — TARİHİ YERİ TANITMA","lines":["Turist: Bu bina ne zaman yapılmış?","Rehber: Bu yapı oldukça eski bir tarihi eserdir. Bölgenin tarihinde önemli bir yere sahiptir.","Turist: Burada kimler yaşamış?","Rehber: Geçmişte burada farklı dönemlerde çeşitli yöneticiler ve önemli kişiler yaşamıştır.","Turist: Binanın içinde neler var?","Rehber: İçeride tarihi odalar, sanat eserleri ve döneme ait bazı eşyalar bulunuyor.","Turist: Fotoğraf çekebilir miyiz?","Rehber: Evet, ancak bazı bölümlerde fotoğraf çekmek yasaktır. O bölümlere geldiğimizde size bilgi vereceğim.","Turist: Bu yapının özel bir hikâyesi var mı?","Rehber: Evet, oldukça ilginç bir hikâyesi var. Şimdi size bu hikâyeyi kısaca anlatacağım.","Turist: Çok merak ediyoruz.","Rehber: O zaman başlayalım. Bu yapı, yüzyıllar boyunca bölgenin kültürel hayatında önemli bir rol oynamıştır."]},{"title":"DİYALOG 3 — TURİST GRUPTAN AYRILIYOR","lines":["Rehber: Arkadaşlar, lütfen burada toplanalım. Bir sonraki durağa geçeceğiz.","Turist: Bir dakika, arkadaşım nerede olduğunu bilmiyorum.","Rehber: En son nerede gördünüz?","Turist: Müzenin girişinde görmüştüm.","Rehber: Tamam. Öncelikle telefonla ulaşmayı deneyelim.","Turist: Arıyorum ama cevap vermiyor.","Rehber: Merak etmeyin. Siz burada bekleyin, ben müze girişine kadar bakacağım.","Turist: Teşekkür ederim.","Rehber: Ayrıca grubun diğer üyelerinin burada kalmasını rica ediyorum.","Turist: Tamam.","Rehber: Arkadaşınızı bulduğumuzda birlikte devam ederiz.","Turist: Umarım bir sorun yoktur.","Rehber: Büyük ihtimalle fotoğraf çekerken biraz geride kalmıştır. Önce müze girişini kontrol edelim.","Turist: Tamam, teşekkür ederim.","Rehber: Rica ederim. Birlikte çözeriz."]},{"title":"DİYALOG 4 — TUR PROGRAMINDA GECİKME","lines":["Turist: Rehber bey, biraz gecikmedik mi?","Rehber: Evet, bugün trafik normalden daha yoğun. Bu nedenle programımız yaklaşık yirmi dakika gecikti.","Turist: Diğer yerleri de görebilecek miyiz?","Rehber: Evet, programı mümkün olduğu kadar korumaya çalışacağız.","Turist: Öğle yemeği saatinde değişiklik olacak mı?","Rehber: Yaklaşık on beş dakikalık bir değişiklik olabilir.","Turist: Peki serbest zamanımız azalacak mı?","Rehber: Hayır, serbest zamanınızı mümkün olduğunca koruyacağız.","Turist: Çok iyi.","Rehber: Şimdi müzeye doğru ilerliyoruz. Orada biraz daha kısa kalacağız.","Turist: Anladık.","Rehber: Programdaki küçük değişiklik için anlayışınız için teşekkür ederim."]}],"grammar":["GRAMER — TUR REHBERLİĞİNDE GEREKLİ TÜRKÇE","Bu bölümde önceki konularda kullanılan zaman, şart, karşılaştırma ve diğer temel yapıları tekrar etmek yerine, rehberlerin tur sırasında sık kullanacağı yeni yapıları öğrenelim.","5.1. “-İ / -I / -U / -Ü” — BELİRTİLİ NESNE","Bu yapı, yapılan işten doğrudan etkilenen belirli nesneyi göstermek için kullanılır.","Örnekler:","Müzeyi ziyaret edeceğiz.\n— Muzeyni ziyorat qilamiz.","Bu binayı göreceğiz.\n— Bu binoni ko‘ramiz.","Tur programını açıklayacağım.\n— Tur dasturini tushuntiraman.","Biletleri kontrol edeceğim.\n— Chiptalarni tekshiraman.","Grubu burada bekleyeceğiz.\n— Guruhni shu yerda kutamiz.","5.2. “-A / -E DOĞRU” — ... TOMON / ...GA QARAB","Biror joyga yo‘nalishni bildirish uchun ishlatiladi.","Örnekler:","Şimdi müzeye doğru yürüyoruz.\n— Hozir muzey tomon yuramiz.","Otelimize doğru ilerliyoruz.\n— Mehmonxonamiz tomon harakatlanyapmiz.","Meydana doğru devam edeceğiz.\n— Maydon tomon davom etamiz.","Girişe doğru yürüyebilirsiniz.\n— Kirish tomonga yurishingiz mumkin.","5.3. “-DEN BİRAZ” — BIR OZ ...DAN","Bu yapı miktarı veya dereceyi yumuşatmak için kullanılır. Rehberlikte nazik ve doğal konuşmaya yardımcı olur.","Örnekler:","Biraz daha yavaş yürüyelim.\n— Biroz sekinroq yuraylik.","Biraz daha dikkatli olalım.\n— Biroz ehtiyotkorroq bo‘laylik.","Biraz daha ilerleyelim.\n— Biroz oldinga yuraylik.","Biraz daha bekleyelim.\n— Biroz ko‘proq kutaylik.","5.4. “-MİŞ” — EŞİTİLEN / AKTARILAN BİLGİ","Bu yapı bir bilgiyi boshqalardan eshitganimizda yoki tarixiy ma’lumotni yetkazayotganimizda ishlatiladi.","Örnekler:","Bu bina 300 yıl önce yapılmış.\n— Bu bino 300 yil oldin qurilgan ekan.","Bu meydan eskiden çok önemliymiş.\n— Bu maydon ilgari juda muhim bo‘lgan ekan.","Burada ünlü bir sanatçı yaşamış.\n— Bu yerda mashhur bir san’atkor yashagan ekan.","Bu eser uzun yıllar burada korunmuş.\n— Bu asar ko‘p yillar davomida shu yerda saqlangan ekan.","5.5. “-DIĞI İÇİN / -DİĞİ İÇİN” — ...GANI UCHUN / SABABLI","Biror voqeaning sababini tushuntirish uchun ishlatiladi.","Örnekler:","Trafik yoğun olduğu için biraz gecikeceğiz.\n— Tirbandlik kuchli bo‘lgani uchun biroz kechikamiz.","Müze kapalı olduğu için başka bir yere gideceğiz.\n— Muzey yopiq bo‘lgani uchun boshqa joyga boramiz.","Hava yağmurlu olduğu için turu içeride devam ettireceğiz.\n— Havo yomg‘irli bo‘lgani uchun turni ichkarida davom ettiramiz.","Grup kalabalık olduğu için burada biraz bekleyeceğiz.\n— Guruh katta bo‘lgani uchun bu yerda biroz kutamiz."],"video":"https://youtu.be/yR8aEpvWEG0?si=Qc_sJloddslJls1Z","document":"assets/materials/day7.docx"},{"day":8,"title":"GİRİŞ","subtitle":"Transfer ve ulaşım hizmetleri, turizm sektörünün en önemli bölümlerinden biridir. Turistlerin havaalanından otele götürülmesi, otelden havaalanına transfer edilmesi, şehir içi ulaşımın organize edilmesi ve grup gezilerinde araçların kullanılması sırasında çalışanların doğru ve anlaşılır Türkçe kullanması gerekir.","words":[["1","Transfer","Transfer"],["2","Ulaşım","Transport / qatnov"],["3","Havaalanı","Aeroport"],["4","Havalimanı","Aeroport"],["5","Uçuş","Parvoz"],["6","Uçuş numarası","Parvoz raqami"],["7","Varış","Yetib kelish"],["8","Kalkış","Jo‘nab ketish"],["9","Araç","Transport vositasi"],["10","Otobüs","Avtobus"],["11","Minibüs","Mikroavtobus"],["12","Otomobil","Yengil avtomobil"],["13","Şoför","Haydovchi"],["14","Yolcu","Yo‘lovchi"],["15","Bagaj","Yuk / bagaj"],["16","Bavul","Chamadon"],["17","El çantası","Qo‘l sumkasi"],["18","Buluşma noktası","Uchrashuv joyi"],["19","Terminal","Terminal"],["20","Çıkış kapısı","Chiqish eshigi"],["21","Otopark","Avtoturargoh"],["22","Güzergâh","Yo‘nalish"],["23","Trafik","Yo‘l harakati / tirbandlik"],["24","Gecikme","Kechikish"],["25","Durak","Bekat"],["26","Emniyet kemeri","Xavfsizlik kamari"],["27","Koltuk","O‘rindiq"],["28","Yol","Yo‘l"],["29","Harita","Xarita"],["30","Navigasyon","Navigatsiya"]],"phrases":[["1","Havaalanına hoş geldiniz.","Aeroportga xush kelibsiz."],["2","Ben transfer görevlisiyim.","Men transfer xodimiman."],["3","Sizi otelinize götüreceğim.","Sizni mehmonxonangizga olib boraman."],["4","Transfer aracınız burada.","Transfer transportingiz shu yerda."],["5","Şoförünüz sizi bekliyor.","Haydovchingiz sizni kutyapti."],["6","Lütfen beni takip edin.","Iltimos, menga ergashing."],["7","Buluşma noktamız çıkış kapısının önünde.","Uchrashuv joyimiz chiqish eshigi oldida."],["8","Bagajınızı almanıza yardımcı olayım.","Bagajingizni olishga yordam beray."],["9","Kaç parça bagajınız var?","Nechta bagajingiz bor?"],["10","Bagajınızı araca yerleştirebilirsiniz.","Bagajingizni transportga joylashtirishingiz mumkin."],["11","Araç yaklaşık on dakika uzaklıkta.","Transport taxminan o‘n daqiqalik masofada."],["12","Otele yaklaşık kırk dakikada ulaşacağız.","Mehmonxonaga taxminan 40 daqiqada yetib boramiz."],["13","Trafik nedeniyle biraz gecikebiliriz.","Tirbandlik sababli biroz kechikishimiz mumkin."],["14","Lütfen emniyet kemerinizi takın.","Iltimos, xavfsizlik kamaringizni taqing."],["15","Araçta boş koltuklar var.","Transportda bo‘sh o‘rindiqlar bor."],["16","Lütfen eşyalarınızı kontrol edin.","Iltimos, buyumlaringizni tekshiring."],["17","Bir eşyanızı araçta unutmuş olabilir misiniz?","Biror buyumingizni transportda unutgan bo‘lishingiz mumkinmi?"],["18","Uçuşunuz gecikmiş.","Parvozingiz kechikibdi."],["19","Merak etmeyin, sizi bekleyeceğiz.","Xavotir olmang, sizni kutamiz."],["20","Şoföre bilgi verdim.","Haydovchiga ma’lumot berdim."],["21","Yeni araç gönderiyoruz.","Yangi transport yuboryapmiz."],["22","Araç değişikliği oldu.","Transport o‘zgardi."],["23","Lütfen burada bekleyin.","Iltimos, shu yerda kuting."],["24","Birkaç dakika içinde geleceğiz.","Bir necha daqiqada kelamiz."],["25","Oteliniz bu yöne doğru.","Mehmonxonangiz shu tomonda."],["26","Bu yol şu anda çok yoğun.","Bu yo‘l hozir juda tirband."],["27","Alternatif bir güzergâh kullanacağız.","Muqobil yo‘nalishdan foydalanamiz."],["28","Havaalanına zamanında ulaşacağız.","Aeroportga o‘z vaqtida yetib boramiz."],["29","Transferiniz sorunsuz tamamlandı.","Transferingiz muammosiz yakunlandi."],["30","İyi yolculuklar dilerim.","Yaxshi safar tilayman."]],"dialogs":[{"title":"DİYALOG 1 — HAVAALANINDA MİSAFİRİ KARŞILAMA","lines":["Transfer Görevlisi: Merhaba, hoş geldiniz. Ben transfer görevlisiyim.","Turist: Merhaba. Bizi otele götürecek araç burada mı?","Transfer Görevlisi: Evet, aracınız otoparkta bizi bekliyor. Önce bagajlarınızı alalım.","Turist: Bagajlarımız burada.","Transfer Görevlisi: Kaç parça bagajınız var?","Turist: Dört büyük bavul ve iki küçük çantamız var.","Transfer Görevlisi: Tamam. Size yardımcı olayım.","Turist: Teşekkür ederiz.","Transfer Görevlisi: Rica ederim. Şimdi lütfen beni takip edin. Araç çıkış kapısının hemen dışında.","Turist: Otele ne kadar sürede ulaşacağız?","Transfer Görevlisi: Normal şartlarda yaklaşık kırk dakika sürüyor. Ancak bugün trafik biraz yoğun.","Turist: Anladım.","Transfer Görevlisi: Merak etmeyin, otelinize güvenli bir şekilde ulaşacağız."]},{"title":"DİYALOG 2 — UÇUŞ GECİKMESİ","lines":["Turist: Merhaba. Transfer aracımızı bulamadık.","Transfer Görevlisi: Merhaba. Uçuş numaranızı alabilir miyim?","Turist: TK458.","Transfer Görevlisi: Bir dakika, kontrol ediyorum. Evet, uçuşunuz yaklaşık kırk dakika gecikmiş.","Turist: Evet, havaalanında bekledik.","Transfer Görevlisi: Sorun değil. Transfer ekibimiz uçuş saatini takip ediyor. Şoförünüz sizi bekliyor.","Turist: Araç hâlâ burada mı?","Transfer Görevlisi: Evet. Şoföre bilgi verdim. Birkaç dakika içinde buluşma noktasına gelecek.","Turist: Çok iyi. Nerede beklemeliyiz?","Transfer Görevlisi: Lütfen çıkış kapısının önünde bekleyin. Ben de sizinle birlikte olacağım.","Turist: Teşekkür ederim.","Transfer Görevlisi: Rica ederim. Uçuş gecikmelerinde endişelenmenize gerek yok. Transferinizi takip ediyoruz."]},{"title":"DİYALOG 3 — BAGAJIN KAYBOLMASI","lines":["Turist: Bir problemimiz var. Bir bavulumuz gelmedi.","Transfer Görevlisi: Geçmiş olsun. Bavulunuzu tarif edebilir misiniz?","Turist: Büyük, siyah bir bavul. Üzerinde kırmızı bir etiket var.","Transfer Görevlisi: Anladım. Önce bagaj bölümündeki görevliye soralım.","Turist: Tamam.","Transfer Görevlisi: Bavulunuzun bagaj numarası var mı?","Turist: Evet, bu belge üzerinde yazıyor.","Transfer Görevlisi: Teşekkür ederim. Görevliye bilgileri vereceğim.","Turist: Bavul bulunursa ne olacak?","Transfer Görevlisi: Bavulunuz bulunduğunda otele gönderilmesini talep edebiliriz.","Turist: Çok iyi olur.","Transfer Görevlisi: Şimdi gerekli bilgileri kaydedelim. Daha sonra sizi gelişmeler hakkında bilgilendireceğiz.","Turist: Yardımınız için teşekkür ederim.","Transfer Görevlisi: Rica ederim. Sorunu çözmek için elimizden geleni yapacağız."]},{"title":"DİYALOG 4 — ARAÇTA YANLIŞLIK","lines":["Turist: Affedersiniz, sanırım bu araç bizim transfer aracımız değil.","Şoför: Rezervasyon bilgilerinizi kontrol edebilir miyim?","Turist: Tabii. Otelimizin adı burada yazıyor.","Şoför: Bir dakika. Evet, burada bir yanlışlık var. Aynı isimde başka bir otel daha bulunuyor.","Turist: O zaman yanlış araca mı bindik?","Şoför: Evet, ancak endişelenmeyin. Durumu hemen transfer merkezine bildireceğim.","Turist: Ne yapmamız gerekiyor?","Şoför: Sizi doğru araca yönlendireceğiz. Diğer araç birkaç dakika içinde buraya gelecek.","Turist: Beklememiz gerekiyor mu?","Şoför: Evet, fakat fazla beklemeyeceksiniz.","Turist: Tamam, teşekkür ederiz.","Şoför: Özür dilerim. Karışıklık için kusura bakmayın.","Turist: Sorun değil.","Şoför: Doğru araç geldiğinde size yardımcı olacağım."]}],"grammar":["GRAMER — TRANSFER VE ULAŞIMDA GEREKLİ TÜRKÇE","Bu bölümde önceki konularda kullanılan temel zaman ve diğer dil bilgisi yapılarını tekrar etmiyoruz. Transfer sırasında yön tarif etmek, sıra belirtmek, tahmin yapmak ve kibar yönlendirme yapmak için yeni yapıları öğreniyoruz.","5.1. “-E / -A KADAR” — ...GACHA / ...GA QADAR","Bu yapı bir yere veya noktaya kadar olan hareketi anlatmak için kullanılır.","Örnekler:","Havaalanına kadar birlikte gideceğiz.\n— Aeroportgacha birga boramiz.","Otelin girişine kadar size eşlik edeceğim.\n— Mehmonxona kirishigacha sizga hamrohlik qilaman.","Terminale kadar yürüyebilirsiniz.\n— Terminalgacha piyoda yurishingiz mumkin.","Araç otoparka kadar gidecek.\n— Transport avtoturargohgacha boradi.","5.2. “ÖNCE / SONRA” — OLDIN / KEYIN","Transfer jarayonida ishlarning ketma-ketligini ko‘rsatish uchun ishlatiladi.","Örnekler:","Önce bagajlarınızı alalım, sonra araca geçelim.\n— Avval bagajlaringizni olaylik, keyin transportga o‘taylik.","Önce uçuş bilgilerini kontrol edelim, sonra transferi ayarlayalım.\n— Avval parvoz ma’lumotlarini tekshiraylik, keyin transferni tashkil qilaylik.","Havaalanına vardıktan sonra beni arayın.\n— Aeroportga yetib kelganingizdan keyin menga qo‘ng‘iroq qiling.","Araç geldikten sonra birlikte çıkacağız.\n— Transport kelgandan keyin birga chiqamiz.","5.3. “GİBİ” — KABI / SINGARI","Biror narsani o‘xshatish yoki taxminiy vaqt-miqdorni aytishda ishlatiladi.","Örnekler:","Yaklaşık kırk dakika gibi bir süre gerekiyor.\n— Taxminan 40 daqiqaga yaqin vaqt kerak.","Beş dakika gibi kısa bir süre bekleyeceğiz.\n— Taxminan besh daqiqacha qisqa vaqt kutamiz.","Bu araç otobüs gibi büyük değil.\n— Bu transport avtobus kabi katta emas.","Şoför sizi bir rehber gibi karşılayacak.\n— Haydovchi sizni gid kabi kutib oladi.","5.4. “ÜZERE” — ... UCHUN / ... ARAFASIDA","Bu yapı özellikle bir işin yapılmak üzere olduğunu veya bir amacın bulunduğunu anlatmak için kullanılır.","Örnekler:","Havaalanına gitmek üzere araçtan çıkıyoruz.\n— Aeroportga borish uchun transportdan chiqamiz.","Misafirleri almak üzere şoför havaalanına gitti.\n— Mehmonlarni olish uchun haydovchi aeroportga ketdi.","Transferi başlatmak üzereyiz.\n— Transferni boshlash arafasidamiz.","Otele gitmek üzere yola çıkıyoruz.\n— Mehmonxonaga borish uchun yo‘lga chiqyapmiz.","5.5. “-DAN / -DEN BİRİ” — ...LARDAN BIRI","Bir guruh ichidan bitta narsani yoki kishini ajratib ko‘rsatish uchun ishlatiladi.","Örnekler:","Bu şehirdeki en güvenli ulaşım seçeneklerinden biri otobüstür.\n— Bu shahardagi eng xavfsiz transport variantlaridan biri avtobusdir.","Bu otel havaalanına en yakın otellerden biri.\n— Bu mehmonxona aeroportga eng yaqin mehmonxonalardan biri.","Bu araç şirketimizin en yeni araçlarından biri.\n— Bu transport kompaniyamizdagi eng yangi transportlardan biri.","Bu güzergâh en kısa yollardan biri.\n— Bu yo‘nalish eng qisqa yo‘llardan biridir."],"video":"https://youtu.be/HKD6kVjSjvI?si=SADFtCT3V_kJjbET","document":"assets/materials/day8.docx"},{"day":9,"title":"GİRİŞ","subtitle":"Tur sırasında her şey her zaman planlandığı gibi gitmeyebilir. Bir turist grubundan ayrılabilir, pasaportunu veya çantasını kaybedebilir, kendini iyi hissetmeyebilir ya da tur programında beklenmeyen bir değişiklik olabilir.","words":[["1","Sorun","Muammo"],["2","Şikâyet","Shikoyat"],["3","Acil durum","Favqulodda vaziyat"],["4","Yardım","Yordam"],["5","Sağlık","Sog‘liq"],["6","Hastane","Kasalxona"],["7","Doktor","Shifokor"],["8","Eczane","Dorixona"],["9","Polis","Politsiya"],["10","Kayıp eşya","Yo‘qolgan buyum"],["11","Pasaport","Pasport"],["12","Cüzdan","Hamyon"],["13","Telefon","Telefon"],["14","Çanta","Sumka"],["15","Belge","Hujjat"],["16","Kimlik","Shaxsni tasdiqlovchi hujjat"],["17","Şikâyet etmek","Shikoyat qilmoq"],["18","Kaybetmek","Yo‘qotmoq"],["19","Bulmak","Topmoq"],["20","Aramak","Qidirmoq / qo‘ng‘iroq qilmoq"],["21","Beklemek","Kutmoq"],["22","Gecikmek","Kechikmoq"],["23","Yaralanmak","Jarohatlanmoq"],["24","Rahatsızlanmak","O‘zini yomon his qilmoq"],["25","Baş dönmesi","Bosh aylanishi"],["26","Ağrı","Og‘riq"],["27","Güvenlik","Xavfsizlik"],["28","Tehlike","Xavf"],["29","Çözüm","Yechim"],["30","Yetkili","Mas’ul xodim"]],"phrases":[["1","Sakin olun, size yardımcı olacağım.","Xotirjam bo‘ling, sizga yordam beraman."],["2","Öncelikle sorunun ne olduğunu anlayalım.","Avvalo muammo nima ekanini tushunib olaylik."],["3","Lütfen bana durumu anlatın.","Iltimos, vaziyatni menga tushuntiring."],["4","Tam olarak ne oldu?","Aniq nima bo‘ldi?"],["5","Ne zamandır bu sorun var?","Bu muammo qachondan beri bor?"],["6","Merak etmeyin, birlikte çözüm bulacağız.","Xavotir olmang, birgalikda yechim topamiz."],["7","Hemen ilgileniyorum.","Darhol shug‘ullanaman."],["8","Yetkili kişiye bilgi vereceğim.","Mas’ul xodimga xabar beraman."],["9","Bu durumu otelle görüşeceğim.","Bu vaziyatni mehmonxona bilan gaplashaman."],["10","Polisle iletişime geçmemiz gerekiyor.","Politsiya bilan bog‘lanishimiz kerak."],["11","Hastaneye gitmeniz gerekebilir.","Kasalxonaga borishingiz kerak bo‘lishi mumkin."],["12","Kendinizi nasıl hissediyorsunuz?","O‘zingizni qanday his qilyapsiz?"],["13","Herhangi bir yeriniz ağrıyor mu?","Biror joyingiz og‘riyaptimi?"],["14","Başınız mı dönüyor?","Boshingiz aylanyaptimi?"],["15","Bir doktora görünmenizi tavsiye ederim.","Shifokorga ko‘rinishingizni tavsiya qilaman."],["16","Pasaportunuzu en son nerede gördünüz?","Pasportingizni oxirgi marta qayerda ko‘rgansiz?"],["17","Eşyanızı nerede kaybettiniz?","Buyumingizni qayerda yo‘qotdingiz?"],["18","Önce bulunduğumuz yeri kontrol edelim.","Avval turgan joyimizni tekshirib ko‘raylik."],["19","Kayıp eşya bölümüne başvuracağız.","Yo‘qolgan buyumlar bo‘limiga murojaat qilamiz."],["20","Bu konuyu hemen bildireceğim.","Bu masala haqida darhol xabar beraman."],["21","Lütfen grubun yanında kalın.","Iltimos, guruh yonida qoling."],["22","Tek başınıza gitmeyin.","Yolg‘iz bormang."],["23","Burada güvenli bir yerde bekleyelim.","Bu yerda xavfsiz joyda kutaylik."],["24","Durumu kontrol ettikten sonra size bilgi vereceğim.","Vaziyatni tekshirgandan keyin sizga ma’lumot beraman."],["25","Programda zorunlu bir değişiklik oldu.","Dasturda majburiy o‘zgarish bo‘ldi."],["26","Bu değişiklik için özür dileriz.","Bu o‘zgarish uchun uzr so‘raymiz."],["27","Alternatif bir çözüm sunabiliriz.","Muqobil yechim taklif qilishimiz mumkin."],["28","Şikâyetinizi anlıyorum.","Shikoyatingizni tushunaman."],["29","Yaşadığınız sorun için özür dilerim.","Siz duch kelgan muammo uchun uzr so‘rayman."],["30","Sorunun çözüldüğünü kontrol edelim.","Muammo hal bo‘lganini tekshirib olaylik."]],"dialogs":[{"title":"DİYALOG 1 — TURİSTİN PASAPORTUNU KAYBETMESİ","lines":["Turist: Rehber bey, büyük bir problemim var. Pasaportumu bulamıyorum.","Rehber: Sakin olun. Size yardımcı olacağım. Pasaportunuzu en son nerede gördünüz?","Turist: Müzeye girmeden önce çantamdaydı.","Rehber: Müzeden çıktıktan sonra çantanızı kontrol ettiniz mi?","Turist: Evet, ama şimdi pasaport yok.","Rehber: Öncelikle bulunduğumuz yeri ve otobüsü kontrol edelim. Belki başka bir yerde kalmıştır.","Turist: Tamam.","Rehber: Daha sonra müze görevlilerine de soracağız.","Turist: Bulamazsak ne yapacağız?","Rehber: Pasaport bulunmazsa polisle iletişime geçmemiz ve gerekli işlemleri yapmamız gerekecek.","Turist: Çok endişeliyim.","Rehber: Merak etmeyin. Sizi yalnız bırakmayacağım. Önce birlikte her yeri kontrol edelim.","Turist: Çok teşekkür ederim.","Rehber: Rica ederim. Şimdi müze girişine dönelim."]},{"title":"DİYALOG 2 — TURİSTİN RAHATSIZLANMASI","lines":["Turist: Rehber bey, kendimi iyi hissetmiyorum.","Rehber: Geçmiş olsun. Kendinizi nasıl hissediyorsunuz?","Turist: Başım dönüyor ve biraz halsizim.","Rehber: Başka bir yeriniz ağrıyor mu?","Turist: Hayır, sadece başım dönüyor.","Rehber: Tamam. Öncelikle burada oturup biraz dinlenelim.","Turist: Tamam.","Rehber: Su ister misiniz?","Turist: Evet, lütfen.","Rehber: Tabii. Eğer kendinizi daha iyi hissetmezseniz doktora veya hastaneye gitmemiz gerekecek.","Turist: Hastane uzak mı?","Rehber: Hayır, buraya yakın bir hastane var. Gerekirse sizi oraya götürebiliriz.","Turist: Şimdilik biraz oturmak istiyorum.","Rehber: Elbette. Siz dinlenin. Ben grubun programını da düzenleyeceğim."]},{"title":"DİYALOG 3 — MÜŞTERİ OTELDEN ŞİKÂYET EDİYOR","lines":["Turist: Rehber bey, otelimizden hiç memnun değilim.","Rehber: Şikâyetinizi anlıyorum. Sorunun ne olduğunu anlatabilir misiniz?","Turist: Odamız çok gürültülü. Gece uyuyamadık.","Rehber: Anladım. Odanız hangi tarafta?","Turist: Restoranın hemen yanında.","Rehber: Tamam. Bu durumu otel yetkilisiyle görüşeceğim.","Turist: Odamızı değiştirebilirler mi?","Rehber: Uygun oda varsa değiştirmelerini isteyeceğim.","Turist: Ayrıca odada sıcak su da yoktu.","Rehber: Bu konuda da bilgi vereceğim. İki sorunu birlikte otel yönetimine ileteceğim.","Turist: Teşekkür ederim. Gerçekten rahatsız olduk.","Rehber: Yaşadığınız sorun için özür dilerim. Öncelikle çözüm bulmaya çalışacağım.","Turist: Tamam, sizden haber bekliyoruz.","Rehber: En kısa sürede size bilgi vereceğim."]},{"title":"DİYALOG 4 — TUR PROGRAMINDA BEKLENMEYEN DEĞİŞİKLİK","lines":["Rehber: Arkadaşlar, programımızla ilgili önemli bir bilgi vermem gerekiyor.","Turist: Ne oldu?","Rehber: Ziyaret edeceğimiz müze bugün teknik bir nedenle kapalı.","Turist: Ama biz özellikle o müzeyi görmek istiyorduk.","Rehber: Bunu anlıyorum. Maalesef müzeyi bugün ziyaret edemiyoruz.","Turist: Peki, başka bir yere gidecek miyiz?","Rehber: Evet. Yakındaki başka bir tarihi alanı ziyaret edeceğiz.","Turist: Orası da güzel mi?","Rehber: Evet, oldukça önemli bir tarihi yer. Ayrıca programda ekstra serbest zaman da bırakacağız.","Turist: Bu değişiklik için ücret ödememiz gerekiyor mu?","Rehber: Hayır, ek bir ücret olmayacak.","Turist: Tamam, o zaman sorun değil.","Rehber: Anlayışınız için teşekkür ederim. Programı mümkün olduğunca güzel şekilde devam ettireceğiz."]}],"grammar":["GRAMER — SORUNLU DURUMLARDA KULLANILAN TÜRKÇE","Bu bölümde rehberning muammoli vaziyatlarda sabab, ehtimol, majburiyat va natijani tushuntirishida kerak bo‘ladigan yangi grammatik tuzilmalar beriladi.","5.1. “-MELİ / -MALI” — KERAK / LOZIM","Bu yapı zarurat va majburiyatni bildiradi.","Örnekler:","Önce polisi aramalıyız.\n— Avval politsiyaga qo‘ng‘iroq qilishimiz kerak.","Pasaport bilgilerini kontrol etmeliyiz.\n— Pasport ma’lumotlarini tekshirishimiz kerak.","Turist hastaneye gitmeli.\n— Sayyoh kasalxonaga borishi kerak.","Grubun yanında kalmalısınız.\n— Guruh yonida qolishingiz kerak.","5.2. “-EBİLİR” — EHTIMOL / MUMKIN","Bu yapı ehtimolni bildiradi. Muammoli vaziyatlarda aniq bo‘lmagan ma’lumotni ehtiyotkorlik bilan aytishda juda foydali.","Örnekler:","Pasaport otelde kalmış olabilir.\n— Pasport mehmonxonada qolgan bo‘lishi mumkin.","Turist müzede olabilir.\n— Sayyoh muzeyda bo‘lishi mumkin.","Trafik nedeniyle gecikme olabilir.\n— Tirbandlik sababli kechikish bo‘lishi mumkin.","Telefon araçta kalmış olabilir.\n— Telefon transportda qolgan bo‘lishi mumkin.","5.3. “EĞER ...” — AGAR...","Shartni yanada aniq va tushunarli ifodalash uchun ishlatiladi.","Örnekler:","Eğer kendinizi kötü hissederseniz bana haber verin.\n— Agar o‘zingizni yomon his qilsangiz, menga xabar bering.","Eğer pasaportu bulamazsak polise başvuracağız.\n— Agar pasportni topa olmasak, politsiyaga murojaat qilamiz.","Eğer oda uygun değilse başka bir oda isteyebiliriz.\n— Agar xona mos bo‘lmasa, boshqa xona so‘rashimiz mumkin.","Eğer sorun devam ederse otel yönetimiyle görüşeceğim.\n— Agar muammo davom etsa, mehmonxona rahbariyati bilan gaplashaman.","5.4. “RAĞMEN” — ...GA QARAMAY","Kutilgan holatga qarama-qarshi vaziyatni bildirish uchun ishlatiladi.","Örnekler:","Trafiğe rağmen havaalanına zamanında ulaştık.\n— Tirbandlikka qaramay, aeroportga o‘z vaqtida yetib bordik.","Yağmura rağmen tur devam etti.\n— Yomg‘irga qaramay, tur davom etdi.","Soruna rağmen müşteri sakin kaldı.\n— Muammoga qaramay, mijoz xotirjam qoldi.","Gecikmeye rağmen programı tamamladık.\n— Kechikishga qaramay, dasturni yakunladik.","5.5. “BU YÜZDEN” — SHU SABABLI / SHUNING UCHUN","Oldingi gapda aytilgan sababning natijasini ko‘rsatadi.","Örnekler:","Müze kapalıydı. Bu yüzden başka bir yere gittik.\n— Muzey yopiq edi. Shu sababli boshqa joyga bordik.","Turist kendini iyi hissetmiyor. Bu yüzden dinlenmesini istedik.\n— Sayyoh o‘zini yaxshi his qilmayapti. Shu sababli dam olishini so‘radik.","Trafik çok yoğundu. Bu yüzden biraz geç kaldık.\n— Tirbandlik juda kuchli edi. Shu sababli biroz kech qoldik.","Pasaport bulunamadı. Bu yüzden polise başvurduk.\n— Pasport topilmadi. Shu sababli politsiyaga murojaat qildik."],"video":"https://youtu.be/wS3FC8zAxI0?si=HKivf12kONJPGb-M","document":"assets/materials/day9.docx"},{"day":10,"title":"4.1. GARSONLAR İÇİN TÜRKÇE","subtitle":"GİRİŞ","words":[["1","Garson","Ofitsiant"],["2","Müşteri","Mijoz"],["3","Masa","Stol"],["4","Sandalye","Stul"],["5","Menü","Menyu"],["6","Sipariş","Buyurtma"],["7","Yemek","Taom / ovqat"],["8","İçecek","Ichimlik"],["9","Kahvaltı","Nonushta"],["10","Öğle yemeği","Tushlik"],["11","Akşam yemeği","Kechki ovqat"],["12","Tatlı","Shirinlik / desert"],["13","Meze","Gazak / zakuska"],["14","Çorba","Sho‘rva"],["15","Salata","Salat"],["16","Ana yemek","Asosiy taom"],["17","Garnitür","Garnir"],["18","Sos","Sous"],["19","Tuz","Tuz"],["20","Biber","Murch"],["21","Kaşık","Qoshiq"],["22","Çatal","Sanchqi"],["23","Bıçak","Pichoq"],["24","Tabak","Likopcha"],["25","Bardak","Stakan"],["26","Peçete","Salfetka"],["27","Hesap","Hisob"],["28","Rezervasyon","Bron / rezervatsiya"],["29","Alerji","Allergiya"],["30","Vejetaryen","Vegetarian"]],"phrases":[["1","Hoş geldiniz.","Xush kelibsiz."],["2","Kaç kişisiniz?","Necha kishisiz?"],["3","Rezervasyonunuz var mı?","Bron qilganmisiz?"],["4","Rezervasyonunuz hangi isimle?","Rezervatsiyangiz kimning nomiga?"],["5","Sizi masanıza alayım.","Sizni stolingizga olib boray."],["6","Buyurun, menünüz.","Marhamat, menyuingiz."],["7","Size biraz zaman vereyim.","Sizga biroz vaqt beray."],["8","Siparişinizi alabilir miyim?","Buyurtmangizni olsam bo‘ladimi?"],["9","Ne almak istersiniz?","Nima olmoqchisiz?"],["10","Bir içecek ister misiniz?","Ichimlik xohlaysizmi?"],["11","Size ne önerebilirim?","Sizga nimani tavsiya qilishim mumkin?"],["12","Bugünün özel yemeği bu.","Bugungi maxsus taom shu."],["13","Bu yemek çok tercih ediliyor.","Bu taomni ko‘p tanlashadi."],["14","Bu yemeğin içinde et var.","Bu taom tarkibida go‘sht bor."],["15","Bu yemek acılıdır.","Bu taom achchiq."],["16","Acısız hazırlayabiliriz.","Achchiqsiz tayyorlashimiz mumkin."],["17","Et veya süt ürünlerine karşı alerjiniz var mı?","Go‘sht yoki sut mahsulotlariga allergiyangiz bormi?"],["18","Yemeğiniz yaklaşık on beş dakikada hazır olur.","Taomingiz taxminan 15 daqiqada tayyor bo‘ladi."],["19","Siparişinizi tekrar edeyim.","Buyurtmangizni takrorlab olay."],["20","Bir şey daha ister misiniz?","Yana biror narsa xohlaysizmi?"],["21","Afiyet olsun.","Yoqimli ishtaha."],["22","Her şey yolunda mı?","Hammasi joyidami?"],["23","Yemeği beğendiniz mi?","Taom sizga yoqdimi?"],["24","Başka bir isteğiniz var mı?","Yana biror istagingiz bormi?"],["25","Hesabı getireyim mi?","Hisobni olib kelaymi?"],["26","Hesabınız burada.","Hisobingiz mana."],["27","Ödemeyi kartla mı yapacaksınız?","To‘lovni karta bilan qilasizmi?"],["28","Nakit veya kartla ödeme yapabilirsiniz.","Naqd yoki karta orqali to‘lashingiz mumkin."],["29","Bir sorun olduysa özür dilerim.","Biror muammo bo‘lgan bo‘lsa, uzr so‘rayman."],["30","Bizi tercih ettiğiniz için teşekkür ederiz.","Bizni tanlaganingiz uchun rahmat."]],"dialogs":[{"title":"DİYALOG 1 — MÜŞTERİYİ KARŞILAMA VE SİPARİŞ ALMA","lines":["Garson: Hoş geldiniz. Kaç kişisiniz?","Müşteri: İki kişiyiz.","Garson: Rezervasyonunuz var mı?","Müşteri: Evet, Ahmet Yılmaz adına rezervasyonumuz var.","Garson: Bir dakika kontrol edeyim. Evet, rezervasyonunuzu buldum. Buyurun, sizi masanıza alayım.","Müşteri: Teşekkür ederiz.","Garson: Buyurun, menüleriniz. İsterseniz size biraz zaman verebilirim.","Müşteri: Teşekkürler. Biz önce içecek siparişi vermek istiyoruz.","Garson: Tabii. Ne almak istersiniz?","Müşteri: İki kahve ve bir şişe su alabilir miyiz?","Garson: Elbette. Kahveleriniz nasıl olsun?","Müşteri: Bir Türk kahvesi, bir filtre kahve.","Garson: Tabii. Yemek siparişinizi biraz sonra alabilirim.","Müşteri: Tamam, teşekkür ederiz.","Garson: Rica ederim."]},{"title":"DİYALOG 2 — MÜŞTERİYE YEMEK TAVSİYE ETME","lines":["Müşteri: Garson bey, burada hangi yemeği tavsiye edersiniz?","Garson: Eğer et seviyorsanız, bugün özel olarak hazırladığımız kebabı tavsiye ederim.","Müşteri: Acılı mı?","Garson: Evet, biraz acılıdır. Ama isterseniz acısız hazırlayabiliriz.","Müşteri: Yanında ne geliyor?","Garson: Pilav, salata ve özel sos ile servis ediyoruz.","Müşteri: Peki, daha hafif bir yemek var mı?","Garson: Tabii. Izgara tavuk ve mevsim salatası sizin için daha uygun olabilir.","Müşteri: Tavuk güzel olur. İçinde süt ürünü var mı?","Garson: Hayır, bu yemeğin içinde süt ürünü yok.","Müşteri: O zaman ızgara tavuk alayım.","Garson: Elbette. Yanında ne içmek istersiniz?","Müşteri: Bir şişe su yeterli.","Garson: Tabii. Siparişinizi hemen hazırlatıyorum."]},{"title":"DİYALOG 3 — ALERJİ VE ÖZEL TALEP","lines":["Müşteri: Sipariş vermeden önce bir şey sormak istiyorum.","Garson: Tabii, buyurun.","Müşteri: Fındığa karşı alerjim var. Yemeklerde fındık kullanılıyor mu?","Garson: Hangi yemeği düşünüyorsunuz?","Müşteri: Salatalardan birini almak istiyorum.","Garson: Bir dakika, mutfağa sorayım.","Müşteri: Tamam.","Garson: Şefimizle görüştüm. Bu salatanın sosunda fındık ürünü bulunuyor.","Müşteri: O zaman onu alamam.","Garson: Size başka bir salata önerebilirim. Bu salatada fındık kullanılmıyor.","Müşteri: Sosunda da yok mu?","Garson: Hayır, sosunda da fındık bulunmuyor. Ancak mutfakta çapraz temas ihtimali konusunda mutfak ekibimizle tekrar kontrol edebilirim.","Müşteri: Evet, lütfen kontrol eder misiniz?","Garson: Elbette. Güvenli bir seçim yapmanız bizim için önemli.","Müşteri: Teşekkür ederim.","Garson: Rica ederim."]},{"title":"DİYALOG 4 — YANLIŞ SİPARİŞ","lines":["Müşteri: Affedersiniz, ben balık sipariş etmiştim ama bana tavuk geldi.","Garson: Çok özür dilerim. Hemen kontrol edeyim.","Müşteri: Siparişimi tekrar söylemiştim.","Garson: Haklısınız. Siparişinizi kontrol ettim, gerçekten balık olarak kaydedilmiş.","Müşteri: Ne kadar beklemem gerekecek?","Garson: Balık yaklaşık on beş dakika içinde hazır olabilir.","Müşteri: On beş dakika biraz uzun.","Garson: Anlıyorum. Mutfakla görüşüp daha kısa sürede hazırlayıp hazırlayamayacaklarını soracağım.","Müşteri: Tamam.","Garson: Şefimiz siparişinizi öncelikli olarak hazırlayacak. Beklemeniz için özür dileriz.","Müşteri: Teşekkür ederim.","Garson: Rica ederim. Bu arada yanlış gelen yemeği masadan alıyorum.","Müşteri: Tamam."]}],"grammar":["GRAMER — GARSONLAR İÇİN PRATİK TÜRKÇE","Bu mavzuda garsonning buyurtmani aniq olish, mijozning istagini aniqlash va taomni qanday tayyorlash kerakligini ifodalashida kerak bo‘ladigan grammatikalar beriladi.","5.1. “-İSTEMEK” — XOHLAMOQ","Bu yapı mijozning xohishini bildirishda ishlatiladi.","Örnekler:","Ne yemek istersiniz?\n— Nima ovqat xohlaysiz?","Bir kahve istiyorum.\n— Bir qahva xohlayman.","Hesap almak istiyoruz.\n— Hisobni olmoqchimiz.","Acısız bir yemek istiyorum.\n— Achchiqsiz taom xohlayman.","5.2. “-MAYI / -MEYİ” — HARAKATNI OBYEKT SIFATIDA ISHLATISH","Bu qo‘shimcha “nimani?” degan savolga javob beradigan fe’l shaklini hosil qiladi.","Örnekler:","Kahve içmeyi ister misiniz?\n— Qahva ichishni xohlaysizmi?","Balık yemeyi tercih ederim.\n— Baliq yeyishni afzal ko‘raman.","Rezervasyon yapmayı düşünüyorum.\n— Rezervatsiya qilishni o‘ylayapman.","Tatlı almayı unutmayın.\n— Desert olishni unutmang.","5.3. “-DAN / -DEN” — QAYSI TAOMDAN / NIMADAN","Bu qo‘shimcha taom yoki mahsulotdan bir qismini, kelib chiqish yoki ajralishni bildirishda ishlatiladi.","Örnekler:","Bu salatın içinde domatesten başka ne var?\n— Bu salat ichida pomidordan tashqari yana nima bor?","Tatlılardan hangisini önerirsiniz?\n— Shirinliklardan qaysi birini tavsiya qilasiz?","Menüden bir yemek seçebilirsiniz.\n— Menyudan bitta taom tanlashingiz mumkin.","İçeceklerden hangisini istersiniz?\n— Ichimliklardan qaysi birini xohlaysiz?","5.4. “-DİKTEN SONRA” — ...GANDAN KEYIN","Bir harakat tugagandan keyin boshqa harakat sodir bo‘lishini bildiradi.","Örnekler:","Siparişinizi aldıktan sonra mutfağa ileteceğim.\n— Buyurtmangizni olganimdan keyin oshxonaga yetkazaman.","Yemeğinizi bitirdikten sonra hesabı getirebilirim.\n— Taomingizni tugatganingizdan keyin hisobni olib kelishim mumkin.","Hesabı kontrol ettikten sonra ödeme yapabilirsiniz.\n— Hisobni tekshirgandan keyin to‘lov qilishingiz mumkin.","5.5. “-MEDEN / -MADAN” — ...MASDAN / ...MAY","Bir ishni qilmasdan turib boshqa ishni bajarishni bildiradi.","Örnekler:","Siparişi kontrol etmeden mutfağa göndermeyelim.\n— Buyurtmani tekshirmasdan oshxonaga yubormaylik.","Hesabı kontrol etmeden ödeme yapmayın.\n— Hisobni tekshirmasdan to‘lov qilmang.","Alerjiyi öğrenmeden yemek önermemeliyiz.\n— Allergiyani bilmasdan taom tavsiya qilmasligimiz kerak.","Müşteriye sormadan siparişi değiştirmeyin.\n— Mijozdan so‘ramasdan buyurtmani o‘zgartirmang."],"video":"https://youtu.be/G0CRqjjt20I?si=msy-iYOtoW0_XPo9","document":"assets/materials/day10.docx"},{"day":11,"title":"GİRİŞ","subtitle":"Barista ve bar çalışanları, kafe, restoran, otel ve diğer yiyecek-içecek işletmelerinde müşterilerle doğrudan iletişim kurar. İçecek siparişi almak, içeceğin özelliklerini açıklamak, müşterinin tercihlerini öğrenmek, özel istekleri yerine getirmek ve siparişi doğru şekilde hazırlamak bu çalışanların temel görevlerindendir.","words":[["1","Barista","Barista"],["2","Bar çalışanı","Bar xodimi"],["3","Kahve","Qahva"],["4","Çay","Choy"],["5","Espresso","Espresso"],["6","Americano","Americano"],["7","Cappuccino","Kappuchino"],["8","Latte","Latte"],["9","Mocha","Mocha"],["10","Türk kahvesi","Turk qahvasi"],["11","Filtre kahve","Filtr qahva"],["12","Süt","Sut"],["13","Köpük","Ko‘pik"],["14","Şeker","Shakar"],["15","Şurup","Sirop"],["16","Buz","Muz"],["17","Bardak","Stakan"],["18","Pipet","Trubochka"],["19","Kapak","Qopqoq"],["20","Sıcak","Issiq"],["21","Soğuk","Sovuq"],["22","Ilık","Iliq"],["23","Tatlı","Shirin"],["24","Şekersiz","Shakarsiz"],["25","Sütlü","Sutli"],["26","Sütsüz","Sutsiz"],["27","Köpüklü","Ko‘pikli"],["28","Sipariş","Buyurtma"],["29","Hazırlamak","Tayyorlamoq"],["30","Servis etmek","Xizmat ko‘rsatmoq / tortmoq"]],"phrases":[["1","Hoş geldiniz.","Xush kelibsiz."],["2","Ne içmek istersiniz?","Nima ichmoqchisiz?"],["3","Size ne hazırlayabilirim?","Sizga nima tayyorlab beray?"],["4","Kahvenizi nasıl istersiniz?","Qahvangizni qanday xohlaysiz?"],["5","Sıcak mı, soğuk mu olsun?","Issiqmi yoki sovuqmi bo‘lsin?"],["6","Şeker ister misiniz?","Shakar xohlaysizmi?"],["7","Süt ekleyelim mi?","Sut qo‘shaylikmi?"],["8","Hangi sütü tercih edersiniz?","Qaysi sutni afzal ko‘rasiz?"],["9","Badem sütümüz de var.","Bodom sutimiz ham bor."],["10","Kahvenizi şekersiz hazırlayabilirim.","Qahvangizni shakarsiz tayyorlashim mumkin."],["11","Daha sert bir kahve ister misiniz?","Kuchliroq qahva xohlaysizmi?"],["12","Daha hafif bir kahve önerebilirim.","Yengilroq qahva tavsiya qilishim mumkin."],["13","Buz miktarını azaltabiliriz.","Muz miqdorini kamaytirishimiz mumkin."],["14","Buz ekleyelim mi?","Muz qo‘shaylikmi?"],["15","Ekstra şurup ister misiniz?","Qo‘shimcha sirop xohlaysizmi?"],["16","Bu içecek vanilya şurubu içeriyor.","Bu ichimlik tarkibida vanil siropi bor."],["17","İçeceğiniz birkaç dakika içinde hazır olacak.","Ichimligingiz bir necha daqiqada tayyor bo‘ladi."],["18","Siparişinizi tekrar edeyim.","Buyurtmangizni takrorlab olay."],["19","İçeceğinizi hemen hazırlıyorum.","Ichimligingizni darhol tayyorlayapman."],["20","Lütfen biraz bekleyebilir misiniz?","Iltimos, biroz kuta olasizmi?"],["21","Buyurun, içeceğiniz hazır.","Marhamat, ichimligingiz tayyor."],["22","Dikkat edin, bardak sıcak.","Ehtiyot bo‘ling, stakan issiq."],["23","Başka bir isteğiniz var mı?","Yana biror istagingiz bormi?"],["24","İçeceğinizi değiştirebilirim.","Ichimligingizni almashtirishim mumkin."],["25","Siparişte bir hata olmuş.","Buyurtmada xatolik bo‘lgan."],["26","Bunun için özür dilerim.","Buning uchun uzr so‘rayman."],["27","Yeni bir içecek hazırlayacağım.","Yangi ichimlik tayyorlayman."],["28","İçeriği hakkında bilgi verebilirim.","Tarkibi haqida ma’lumot bera olaman."],["29","Afiyet olsun.","Yoqimli ishtaha."],["30","Yine bekleriz.","Yana kutib qolamiz."]],"dialogs":[{"title":"DİYALOG 1 — KAHVE SİPARİŞİ ALMA","lines":["Barista: Hoş geldiniz. Ne içmek istersiniz?","Müşteri: Bir latte alabilir miyim?","Barista: Tabii. Sıcak mı, soğuk mu olsun?","Müşteri: Sıcak olsun.","Barista: Şeker ister misiniz?","Müşteri: Hayır, şekersiz olsun.","Barista: Tabii. Normal süt mü istersiniz?","Müşteri: Badem sütü var mı?","Barista: Evet, badem sütümüz var.","Müşteri: O zaman badem sütlü latte alayım.","Barista: Elbette. Başka bir isteğiniz var mı?","Müşteri: Hayır, teşekkür ederim.","Barista: Rica ederim. İçeceğiniz birkaç dakika içinde hazır olacak."]},{"title":"DİYALOG 2 — MÜŞTERİYE KAHVE TAVSİYE ETME","lines":["Müşteri: Kahve konusunda pek bilgim yok. Bana bir kahve önerebilir misiniz?","Barista: Tabii. Kahvenizi sert mi, daha hafif mi seviyorsunuz?","Müşteri: Çok sert olmasın.","Barista: O zaman latte veya cappuccino önerebilirim.","Müşteri: Aralarındaki fark nedir?","Barista: Latte daha fazla süt içerir. Cappuccino ise daha yoğun süt köpüğüne sahiptir.","Müşteri: Ben sütlü kahve seviyorum.","Barista: O zaman latte sizin için daha uygun olabilir.","Müşteri: Güzel. Vanilya ekleyebilir miyiz?","Barista: Evet, vanilya şurubu ekleyebiliriz.","Müşteri: O zaman vanilyalı latte istiyorum.","Barista: Tabii. Sıcak olarak hazırlıyorum.","Müşteri: Teşekkür ederim.","Barista: Rica ederim."]},{"title":"DİYALOG 3 — SOĞUK İÇECEK VE ÖZEL İSTEK","lines":["Müşteri: Bir iced coffee alabilir miyim?","Barista: Elbette. Buz miktarı normal olsun mu?","Müşteri: Çok fazla buz istemiyorum.","Barista: Tabii. Buz miktarını azaltabiliriz.","Müşteri: Biraz da vanilya şurubu ekleyebilir misiniz?","Barista: Tabii. Kaç pompa vanilya şurubu istersiniz?","Müşteri: Bir pompa yeterli.","Barista: Tamam. Şeker eklemiyoruz, değil mi?","Müşteri: Evet, şeker istemiyorum.","Barista: Siparişinizi tekrar edeyim: az buzlu, şekersiz ve bir pompa vanilya şuruplu iced coffee.","Müşteri: Evet, doğru.","Barista: Harika. Hemen hazırlıyorum."]},{"title":"DİYALOG 4 — YANLIŞ İÇECEK HAZIRLANMASI","lines":["Müşteri: Affedersiniz, ben cappuccino sipariş etmiştim.","Barista: Bir dakika kontrol edeyim.","Müşteri: Bana latte verilmiş.","Barista: Haklısınız. Siparişte bir hata olmuş. Bunun için özür dilerim.","Müşteri: Sorun değil, ama cappuccino istemiştim.","Barista: Elbette. Size hemen yeni bir cappuccino hazırlayacağım.","Müşteri: Ne kadar beklemem gerekiyor?","Barista: Yaklaşık üç dakika sürecek.","Müşteri: Tamam.","Barista: Bu arada yanlış hazırlanan içeceği değiştireceğim.","Müşteri: Teşekkür ederim.","Barista: Rica ederim. Yeni içeceğinizi hemen hazırlıyorum.","Müşteri: Tamam, teşekkürler.","Barista: Afiyet olsun."]}],"grammar":["GRAMER — BARİSTA VE BAR ÇALIŞANLARI İÇİN PRATİK TÜRKÇE","Bu mavzuda ichimlikni ta’riflash, mijozning xohishini aniqlash va biror narsani qo‘shish yoki o‘zgartirishni ifodalashda kerak bo‘ladigan grammatikalar o‘rganiladi.","5.1. “-DAN / -DEN DAHA” — ...DAN KO‘RA / ...DAN KO‘PROQ","Ikki narsani solishtirish uchun ishlatiladi.","Örnekler:","Latte, americano'dan daha yumuşaktır.\n— Latte Americanodan ko‘ra yumshoqroq.","Bu kahve diğerinden daha sert.\n— Bu qahva boshqasidan kuchliroq.","Soğuk kahve, sıcak kahveden daha hafif olabilir.\n— Sovuq qahva issiq qahvadan yengilroq bo‘lishi mumkin.","5.2. “-DAN / -DEN ... İLE” — ...DAN ... BILAN","Mahsulot yoki ichimlik tarkibini tushuntirishda ishlatilishi mumkin.","Örnekler:","Kahve süt ile hazırlanıyor.\n— Qahva sut bilan tayyorlanadi.","Bu içecek badem sütü ile hazırlanıyor.\n— Bu ichimlik bodom suti bilan tayyorlanadi.","Tatlı çikolata ile servis ediliyor.\n— Desert shokolad bilan tortiladi.","5.3. “-MİŞ / -MIŞ” — ESLATISH, ESHITILGAN MA’LUMOT","Mijozga yangi ma’lumotni aytishda yoki boshqa xodimdan eshitilgan ma’lumotni yetkazishda ishlatilishi mumkin.","Örnekler:","Bugün yeni bir kahve gelmiş.\n— Bugun yangi qahva kelibdi.","Şef yeni bir içecek hazırlamış.\n— Oshpaz yangi ichimlik tayyorlabdi.","Bu kahve çok beğenilmiş.\n— Bu qahva juda yoqibdi / ko‘pchilikka yoqibdi.","Eslatma: Bu shakl turk tilida “eshitdim / bilib qoldim” mazmunini ham beradi.","5.4. “-KEN” — ...PAYTIDA / ...GANDA","Bir ish davom etayotgan vaqtda boshqa harakatni bildirish uchun ishlatiladi.","Örnekler:","Kahve hazırlanırken lütfen bekleyin.\n— Qahva tayyorlanayotgan paytda, iltimos, kuting.","Süt eklerken dikkatli olmalıyız.\n— Sut qo‘shayotganda ehtiyot bo‘lishimiz kerak.","Sipariş alırken müşteriyi dikkatle dinleyin.\n— Buyurtma olayotganda mijozni diqqat bilan tinglang.","Kahveyi hazırlarken bardak sıcak olabilir.\n— Qahva tayyorlanayotganda stakan issiq bo‘lishi mumkin.","5.5. “HEM ... HEM DE ...” — HAM ... HAM ...","Ikki xususiyat yoki ikki harakatni birgalikda ifodalash uchun ishlatiladi.","Örnekler:","Bu kahve hem hafif hem de aromalıdır.\n— Bu qahva ham yengil, ham xushbo‘y.","Hem sıcak hem de soğuk içeceklerimiz var.\n— Bizda ham issiq, ham sovuq ichimliklar bor.","Hem süt hem de şurup ekleyebiliriz.\n— Ham sut, ham sirop qo‘shishimiz mumkin."],"video":"https://youtu.be/IOaX1zesS4U?si=BMv2UzM-3XmVBjsP","document":"assets/materials/day11.docx"},{"day":12,"title":"GİRİŞ","subtitle":"Mutfak ve servis çalışanları bir restoranın başarılı şekilde çalışması için birlikte hareket eder. Garson müşteriden siparişi alır, mutfak ekibine doğru şekilde iletir ve hazırlanan yemeği zamanında müşteriye ulaştırır.","words":[["1","Mutfak","Oshxona"],["2","Aşçı","Oshpaz"],["3","Şef","Bosh oshpaz / shef"],["4","Mutfak çalışanı","Oshxona xodimi"],["5","Servis","Xizmat / servis"],["6","Garson","Ofitsiant"],["7","Sipariş","Buyurtma"],["8","Malzeme","Masalliq / kerakli mahsulot"],["9","Sebze","Sabzavot"],["10","Et","Go‘sht"],["11","Tavuk","Tovuq go‘shti"],["12","Balık","Baliq"],["13","Pirinç","Guruch"],["14","Un","Un"],["15","Yağ","Yog‘"],["16","Tuz","Tuz"],["17","Baharat","Ziravor"],["18","Tencere","Qozon / kastryulka"],["19","Tava","Tova"],["20","Fırın","Duxovka / pech"],["21","Buzdolabı","Muzlatkich"],["22","Ocak","Plita"],["23","Tabak","Likopcha"],["24","Porsiyon","Porsiya"],["25","Hazırlamak","Tayyorlamoq"],["26","Pişirmek","Pishirmoq"],["27","Kızartmak","Qovurmoq"],["28","Doğramak","To‘g‘ramoq"],["29","Servise çıkarmak","Servisga chiqarish"],["30","Hazır","Tayyor"]],"phrases":[["1","Yeni bir sipariş geldi.","Yangi buyurtma keldi."],["2","Siparişi mutfağa iletiyorum.","Buyurtmani oshxonaga yetkazaman."],["3","Siparişi kontrol eder misiniz?","Buyurtmani tekshirib ko‘rasizmi?"],["4","Bu sipariş hangi masa için?","Bu buyurtma qaysi stol uchun?"],["5","Kaç porsiyon hazırlanacak?","Necha porsiya tayyorlanadi?"],["6","Bu yemek hazır mı?","Bu taom tayyormi?"],["7","Yemek ne zaman hazır olur?","Taom qachon tayyor bo‘ladi?"],["8","Yaklaşık on dakika sürer.","Taxminan o‘n daqiqa davom etadi."],["9","Siparişi biraz hızlandırabilir miyiz?","Buyurtmani biroz tezlashtira olamizmi?"],["10","Müşteri bekliyor.","Mijoz kutyapti."],["11","Bu yemek çok acı olmasın.","Bu taom juda achchiq bo‘lmasin."],["12","Soğan eklemeyin, lütfen.","Iltimos, piyoz qo‘shmang."],["13","Müşteri soğan istemiyor.","Mijoz piyoz xohlamayapti."],["14","Bu sipariş özel hazırlanacak.","Bu buyurtma maxsus tayyorlanadi."],["15","Alerji konusunda dikkatli olalım.","Allergiya masalasida ehtiyot bo‘laylik."],["16","Bu malzeme kalmamış.","Bu masalliq qolmagan."],["17","Başka bir malzeme kullanabilir miyiz?","Boshqa masalliq ishlatsak bo‘ladimi?"],["18","Yemek biraz daha pişmeli.","Taom yana biroz pishishi kerak."],["19","Sipariş hazır.","Buyurtma tayyor."],["20","Servise çıkarabilirsiniz.","Servisga chiqarishingiz mumkin."],["21","Bu masa için hazır.","Bu stol uchun tayyor."],["22","Lütfen sıcak servis edin.","Iltimos, issiq holda torting."],["23","Tabak hazır değil.","Likopcha tayyor emas."],["24","Eksik bir şey var mı?","Yetishmayotgan narsa bormi?"],["25","Siparişte bir hata var.","Buyurtmada xato bor."],["26","Bu yemek yanlış hazırlanmış.","Bu taom noto‘g‘ri tayyorlangan."],["27","Müşteri beklemek istemiyor.","Mijoz kutishni xohlamayapti."],["28","Yeni bir porsiyon hazırlayalım.","Yangi bir porsiya tayyorlaylik."],["29","Şefe haber vereceğim.","Shefga xabar beraman."],["30","Servis için teşekkürler.","Servis uchun rahmat."]],"dialogs":[{"title":"DİYALOG 1 — YENİ SİPARİŞİN MUTFAĞA İLETİLMESİ","lines":["Garson: Şef, yeni bir sipariş geldi.","Şef: Hangi masa için?","Garson: 12 numaralı masa için. İki porsiyon tavuk, bir salata ve bir çorba.","Şef: Tavuk nasıl hazırlanacak?","Garson: Bir porsiyon normal, diğerinde acı baharat olmayacak.","Şef: Tamam. Salatada özel bir istek var mı?","Garson: Evet. Müşteri soğan istemiyor.","Şef: Anladım. Çorba normal mi?","Garson: Evet, normal.","Şef: Tamam, siparişi hazırlıyoruz.","Garson: Yaklaşık ne kadar sürer?","Şef: Çorba ve salata beş dakika içinde hazır olur. Tavuk yaklaşık on beş dakika sürecek.","Garson: Tamam, müşteriye bilgi vereceğim.","Şef: Tavuk hazır olduğunda sana haber vereceğim.","Garson: Teşekkürler."]},{"title":"DİYALOG 2 — ÖZEL SİPARİŞ","lines":["Garson: Şef, 8 numaralı masanın özel bir isteği var.","Şef: Nedir?","Garson: Müşteri et yemeğinin içinde soğan istemiyor.","Şef: Başka bir isteği var mı?","Garson: Evet. Yemeğin çok acı olmamasını istiyor.","Şef: Tamam. Soğan koymayacağız ve baharatı azaltacağız.","Garson: Ayrıca müşterinin süt ürünlerine karşı hassasiyeti olduğunu söyledi.","Şef: O zaman sosu da kontrol etmeliyiz.","Garson: Sosun içinde süt var mı?","Şef: Evet, normal sosun içinde süt ürünü var.","Garson: Alternatif bir sos hazırlayabilir miyiz?","Şef: Evet, zeytinyağlı bir sos hazırlayabiliriz.","Garson: Harika. Müşteriye bilgi vereceğim.","Şef: Tamam. Bu siparişi ayrı hazırlayalım."]},{"title":"DİYALOG 3 — SİPARİŞİN GECİKMESİ","lines":["Garson: Şef, 15 numaralı masa yemeklerini bekliyor.","Şef: Sipariş ne zaman geldi?","Garson: Yaklaşık yirmi dakika önce.","Şef: Tavuk hâlâ pişiyor.","Garson: Müşteri biraz daha beklemek istemiyor.","Şef: Tavuk birkaç dakika içinde hazır olacak.","Garson: Tam olarak ne kadar sürer?","Şef: Beş dakika daha.","Garson: Tamam. Müşteriye bilgi vereceğim.","Şef: Gecikme için özür dileyin.","Garson: Tabii.","Şef: Ayrıca salatayı hemen çıkaralım.","Garson: Tamam, salatayı şimdi götürüyorum.","Şef: Tavuk hazır olduğunda sana haber vereceğim."]},{"title":"DİYALOG 4 — YANLIŞ YEMEK HAZIRLANMASI","lines":["Garson: Şef, bir sorun var.","Şef: Ne oldu?","Garson: 10 numaralı masa balık sipariş etmişti ama tavuk hazırlanmış.","Şef: Sipariş fişini kontrol ettiniz mi?","Garson: Evet. Fişte balık yazıyor.","Şef: O zaman mutfakta bir hata olmuş.","Garson: Müşteri bekliyor. Ne yapalım?","Şef: Balığı hemen hazırlayalım.","Garson: Ne kadar sürecek?","Şef: Yaklaşık on dakika.","Garson: Tamam. Müşteriden özür dileyeceğim.","Şef: Ben de mutfak ekibiyle konuşacağım.","Garson: Teşekkürler.","Şef: Önemli olan hatayı hızlı şekilde düzeltmek."]}],"grammar":["GRAMER — MUTFAK VE SERVİS ÇALIŞANLARI İÇİN PRATİK TÜRKÇE","Bu mavzuda oshxona va servis xodimlari buyurtma, jarayon, ketma-ket harakat va taomning qanday holatda bo‘lishi kerakligini tushuntirishda ishlatadigan grammatikalar beriladi.","5.1. “-DIĞI ZAMAN / -DİĞİ ZAMAN” — ...GAN PAYTDA / ...GANDA","Biror harakat sodir bo‘lgan vaqtda boshqa ishni ifodalash uchun ishlatiladi.","Örnekler:","Yemek hazır olduğu zaman bana haber verin.\n— Taom tayyor bo‘lgan paytda menga xabar bering.","Müşteri geldiği zaman siparişi alalım.\n— Mijoz kelganda buyurtmasini olaylik.","Şef geldiği zaman durumu anlatacağım.\n— Shef kelganda vaziyatni tushuntiraman.","5.2. “-MAK ÜZERE” — ...ISH UCHUN / ...ISH ARAFASIDA","Maqsad yoki bir ishni bajarishga yaqin holatni bildiradi.","Örnekler:","Siparişi hazırlamak üzere mutfağa geçiyorum.\n— Buyurtmani tayyorlash uchun oshxonaga o‘tyapman.","Servise çıkarmak üzere yemekleri hazırlıyoruz.\n— Taomlarni servisga chiqarish uchun tayyorlayapmiz.","Müşteriye bilgi vermek üzere masaya gidiyorum.\n— Mijozga ma’lumot berish uchun stolga ketyapman.","5.3. “-MAYA BAŞLAMAK” — ...NI BOSHLAMOQ","Biror harakatning boshlanishini bildiradi.","Örnekler:","Siparişi hazırlamaya başladık.\n— Buyurtmani tayyorlashni boshladik.","Şef yemeği pişirmeye başladı.\n— Shef taomni pishirishni boshladi.","Mutfak çalışanları hazırlık yapmaya başladı.\n— Oshxona xodimlari tayyorgarlik ko‘rishni boshlashdi.","5.4. “-MAYA DEVAM ETMEK” — ...NI DAVOM ETTIRMOQ","Boshlangan harakatning davom etayotganini bildiradi.","Örnekler:","Yemek pişmeye devam ediyor.\n— Taom pishishda davom etyapti.","Mutfak ekibi hazırlanmaya devam ediyor.\n— Oshxona jamoasi tayyorgarlikni davom ettiryapti.","Siparişler gelmeye devam ediyor.\n— Buyurtmalar kelishda davom etyapti.","5.5. “-MASI / -MESİ GEREKİYOR” — ...ISHI KERAK","Biror ishning bajarilishi kerakligini rasmiyroq va professional tarzda bildirish uchun ishlatiladi.","Örnekler:","Bu yemek sıcak servis edilmesi gerekiyor.\n— Bu taom issiq holda tortilishi kerak.","Siparişin kontrol edilmesi gerekiyor.\n— Buyurtma tekshirilishi kerak.","Alerjinin mutfağa bildirilmesi gerekiyor.\n— Allergiya haqida oshxonaga xabar berilishi kerak.","Özel siparişin ayrı hazırlanması gerekiyor.\n— Maxsus buyurtma alohida tayyorlanishi kerak."],"video":"https://youtu.be/2-fJjSM9RNM?si=RFJ8dZV3rRV7uWPg","document":"assets/materials/day12.docx"},{"day":13,"title":"5.1. MÜŞTERİLERLE GÜNLÜK PROFESYONEL İLETİŞİM","subtitle":"GİRİŞ","words":[["1","Müşteri","Mijoz"],["2","Misafir","Mehmon"],["3","Hizmet","Xizmat"],["4","Yardım","Yordam"],["5","Bilgi","Ma’lumot"],["6","İstek","Istak"],["7","Talep","Talab / so‘rov"],["8","Soru","Savol"],["9","Cevap","Javob"],["10","Açıklama","Tushuntirish"],["11","Öneri","Tavsiya"],["12","Seçenek","Variant"],["13","Tercih","Tanlov / afzal ko‘rish"],["14","Memnuniyet","Mamnunlik"],["15","Şikâyet","Shikoyat"],["16","Sorun","Muammo"],["17","Çözüm","Yechim"],["18","Destek","Ko‘mak"],["19","Yardımcı","Yordamchi"],["20","Uygun","Mos / qulay"],["21","Müsait","Bo‘sh / mavjud"],["22","Meşgul","Band"],["23","Beklemek","Kutmoq"],["24","Görüşmek","Suhbatlashmoq / gaplashmoq"],["25","İletişim","Muloqot / aloqa"],["26","Telefon","Telefon"],["27","Mesaj","Xabar"],["28","Yetkili","Mas’ul xodim"],["29","Departman","Bo‘lim"],["30","Memnun","Mamnun"]],"phrases":[["1","Size nasıl yardımcı olabilirim?","Sizga qanday yordam bera olaman?"],["2","Buyurun, sizi dinliyorum.","Marhamat, sizni tinglayapman."],["3","Size gerekli bilgiyi verebilirim.","Sizga kerakli ma’lumotni bera olaman."],["4","Sorunuzu anlıyorum.","Savolingizni tushunyapman."],["5","Bir dakika, kontrol edeyim.","Bir daqiqa, tekshirib olay."],["6","Hemen bilgi vereceğim.","Darhol ma’lumot beraman."],["7","Konuyu kontrol etmem gerekiyor.","Masalani tekshirishim kerak."],["8","Size birkaç seçenek sunabilirim.","Sizga bir nechta variant taklif qila olaman."],["9","Sizin için daha uygun bir seçenek var.","Siz uchun qulayroq variant bor."],["10","Tercihinizi öğrenebilir miyim?","Tanlovingizni bilsam bo‘ladimi?"],["11","Başka bir isteğiniz var mı?","Yana biror istagingiz bormi?"],["12","Herhangi bir sorunuz var mı?","Biror savolingiz bormi?"],["13","Size ayrıntılı olarak açıklayayım.","Sizga batafsil tushuntirib beray."],["14","Bu konuda size yardımcı olabilirim.","Bu masalada sizga yordam bera olaman."],["15","İlgili departmanla görüşeceğim.","Tegishli bo‘lim bilan gaplashaman."],["16","Yetkili kişiye bilgi vereceğim.","Mas’ul xodimga xabar beraman."],["17","Lütfen birkaç dakika bekleyin.","Iltimos, bir necha daqiqa kuting."],["18","Beklettiğimiz için özür dileriz.","Kuttirganimiz uchun uzr so‘raymiz."],["19","Anlayışınız için teşekkür ederiz.","Tushunganingiz uchun rahmat."],["20","İlginiz için teşekkür ederiz.","E’tiboringiz uchun rahmat."],["21","Memnuniyetiniz bizim için önemli.","Sizning mamnunligingiz biz uchun muhim."],["22","Yaşadığınız sorun için özür dilerim.","Siz duch kelgan muammo uchun uzr so‘rayman."],["23","Sorunu çözmeye çalışacağım.","Muammoni hal qilishga harakat qilaman."],["24","Alternatif bir çözüm sunabiliriz.","Muqobil yechim taklif qilishimiz mumkin."],["25","Size en kısa zamanda dönüş yapacağım.","Sizga imkon qadar tezroq javob beraman."],["26","Bilgileri size mesaj olarak gönderebilirim.","Ma’lumotlarni sizga xabar orqali yuborishim mumkin."],["27","İletişim bilgilerinizi alabilir miyim?","Aloqa ma’lumotlaringizni olsam bo‘ladimi?"],["28","Her şey sizin için uygun mu?","Hammasi siz uchun qulaymi?"],["29","Başka bir konuda yardımcı olabilir miyim?","Yana boshqa masalada yordam bera olamanmi?"],["30","Sizi tekrar ağırlamaktan memnuniyet duyarız.","Sizni yana kutib olishdan mamnun bo‘lamiz."]],"dialogs":[{"title":"DİYALOG 1 — MÜŞTERİ BİLGİ İSTİYOR","lines":["Müşteri: Merhaba, size bir şey sormak istiyorum.","Çalışan: Merhaba, buyurun. Sizi dinliyorum.","Müşteri: Yarın şehir merkezine gitmek istiyoruz. Buradan nasıl gidebiliriz?","Çalışan: Elbette. Size birkaç seçenek sunabilirim.","Müşteri: Otobüsle gitmek istiyoruz.","Çalışan: Otobüs durağı otelin yaklaşık beş dakika uzağında.","Müşteri: Bilet nereden alabiliriz?","Çalışan: Bileti duraktaki gişeden veya kartla alabilirsiniz.","Müşteri: Şehir merkezine ulaşmak ne kadar sürüyor?","Çalışan: Trafiğe bağlı olarak yaklaşık yirmi beş dakika sürüyor.","Müşteri: Çok teşekkür ederim.","Çalışan: Rica ederim. Başka bir konuda yardımcı olabilir miyim?","Müşteri: Hayır, teşekkürler.","Çalışan: İyi gezmeler dilerim."]},{"title":"DİYALOG 2 — MÜŞTERİNİN ÖZEL TALEBİ","lines":["Müşteri: Size bir ricam olacak.","Çalışan: Tabii, buyurun. Nasıl yardımcı olabilirim?","Müşteri: Yarın sabah erken çıkmam gerekiyor. Kahvaltı daha erken hazırlanabilir mi?","Çalışan: Normal kahvaltı saatimiz saat yedide başlıyor.","Müşteri: Benim saat altıda çıkmam gerekiyor.","Çalışan: Konuyu restoran departmanıyla görüşebilirim.","Müşteri: Çok iyi olur.","Çalışan: Size paket kahvaltı hazırlama seçeneklerini de sorabilirim.","Müşteri: Evet, lütfen.","Çalışan: Elbette. Bilgiyi aldıktan sonra size haber vereceğim.","Müşteri: Çok teşekkür ederim.","Çalışan: Rica ederim. Memnuniyetiniz bizim için önemli."]},{"title":"DİYALOG 3 — MÜŞTERİ BİR ŞEYİ ANLAMIYOR","lines":["Müşteri: Özür dilerim, bu bilgiyi tam anlayamadım.","Çalışan: Hiç sorun değil. Tekrar açıklayayım.","Müşteri: Transfer saatini anlamadım.","Çalışan: Tabii. Transfer aracınız yarın sabah saat sekizde otelin önünden hareket edecek.","Müşteri: Saat sekizde burada olmamız gerekiyor, değil mi?","Çalışan: Evet. Hatta birkaç dakika önce hazır olmanızı öneririm.","Müşteri: Peki, bagajlarımızı ne zaman hazırlamalıyız?","Çalışan: Sabah çıkmadan önce bagajlarınızı resepsiyonun yanındaki alana bırakabilirsiniz.","Müşteri: Şimdi daha iyi anladım.","Çalışan: Harika. Başka bir sorunuz varsa memnuniyetle cevaplarım.","Müşteri: Teşekkür ederim.","Çalışan: Rica ederim."]},{"title":"DİYALOG 4 — MÜŞTERİ BEKLETİLİYOR","lines":["Müşteri: Yaklaşık on dakikadır bekliyorum.","Çalışan: Beklettiğimiz için özür dilerim.","Müşteri: Bir konuda yardım istemiştim.","Çalışan: Evet, hatırlıyorum. Konuyu ilgili departmana ilettim.","Müşteri: Henüz cevap gelmedi mi?","Çalışan: Henüz cevap gelmedi. Hemen tekrar kontrol ediyorum.","Müşteri: Ne kadar daha beklemem gerekiyor?","Çalışan: Birkaç dakika içinde size bilgi vermeye çalışacağım.","Müşteri: Tamam.","Çalışan: Anlayışınız için teşekkür ederim.","Müşteri: Rica ederim.","Çalışan: Konu hakkında bilgi gelir gelmez size haber vereceğim."]}],"grammar":["GRAMER — MÜŞTERİLERLE PROFESYONEL İLETİŞİM","Bu mavzuda turizm xodimlari mijoz bilan muloyim so‘rash, fikrini ehtiyotkorlik bilan bildirish, imkoniyat taklif qilish va professional tarzda murojaat qilish uchun kerak bo‘ladigan grammatik shakllarni o‘rganadi.","5.1. “-ABİLİR MİYİM?” — MULoyIM SO‘ROV","Biror narsani muloyim tarzda so‘rash yoki ruxsat olish uchun ishlatiladi.","Örnekler:","Size bir soru sorabilir miyim?\n— Sizga bir savol bersam bo‘ladimi?","Bilgilerinizi alabilir miyim?\n— Ma’lumotlaringizni olsam bo‘ladimi?","Rezervasyonunuzu kontrol edebilir miyim?\n— Rezervatsiyangizni tekshirsam bo‘ladimi?","Size yardımcı olabilir miyim?\n— Sizga yordam bera olamanmi?","5.2. “BENCE” — MENINGIMCHA","Shaxsiy fikrni yumshoq va professional tarzda bildirish uchun ishlatiladi.","Örnekler:","Bence bu seçenek sizin için daha uygun.\n— Menimcha, bu variant siz uchun qulayroq.","Bence sabah gitmeniz daha iyi olur.\n— Menimcha, ertalab borganingiz yaxshiroq bo‘ladi.","Bence bu otel aileler için uygun.\n— Menimcha, bu mehmonxona oilalar uchun mos.","5.3. “BANA GÖRE” — MENING FIKRIMCHA / MENINGCHA","“Bence”ga yaqin, lekin fikrni shaxsiy nuqtai nazardan ifodalashda ishlatiladi.","Örnekler:","Bana göre bu hizmet daha uygun.\n— Mening fikrimcha, bu xizmat qulayroq.","Bana göre bu tur aileler için daha iyi.\n— Meningcha, bu tur oilalar uchun yaxshiroq.","Bana göre en uygun saat sabah saatleri.\n— Mening fikrimcha, eng qulay vaqt ertalab.","5.4. “EĞER İSTERSENİZ” — AGAR XOHLASANGIZ","Mijozga variant yoki yordamni muloyim taklif qilishda ishlatiladi.","Örnekler:","Eğer isterseniz size başka bir seçenek sunabilirim.\n— Agar xohlasangiz, sizga boshqa variant taklif qilishim mumkin.","Eğer isterseniz rezervasyonu kontrol edebilirim.\n— Agar xohlasangiz, rezervatsiyani tekshirib bera olaman.","Eğer isterseniz ilgili departmanla görüşebilirim.\n— Agar xohlasangiz, tegishli bo‘lim bilan gaplashishim mumkin.","5.5. “-A / -E UYGUN” — ...GA MOS / QULAY","Turizm sohasida xizmat, vaqt, joy yoki variantning mijozga mosligini aytishda juda ko‘p ishlatiladi.","Örnekler:","Bu seçenek sizin için uygun.\n— Bu variant siz uchun mos.","Saat üç sizin için uygun mu?\n— Soat uch siz uchun qulaymi?","Bu otel çocuklu aileler için uygun.\n— Bu mehmonxona bolali oilalar uchun mos.","Bu saat bizim için uygun değil.\n— Bu vaqt biz uchun qulay emas."],"video":"https://youtu.be/3ngzvH3OANk?si=Th1Ae7N0C1AeGTso","document":"assets/materials/day13.docx"},{"day":14,"title":"GİRİŞ","subtitle":"Turizm sektöründe çalışanlar zaman zaman beklenmeyen sorunlarla karşılaşabilir. Müşteri aldığı hizmetten memnun olmayabilir, rezervasyonda hata olabilir, transfer gecikebilir veya bir misafir kendisini kötü hissedebilir.","words":[["1","Şikâyet","Shikoyat"],["2","Sorun","Muammo"],["3","Acil durum","Favqulodda vaziyat"],["4","Çözüm","Yechim"],["5","Özür","Uzr"],["6","Hata","Xato"],["7","Gecikme","Kechikish"],["8","İptal","Bekor qilish"],["9","Değişiklik","O‘zgarish"],["10","Mağduriyet","Noqulay vaziyat / zarar ko‘rish"],["11","Yardım","Yordam"],["12","Destek","Ko‘mak"],["13","Güvenlik","Xavfsizlik"],["14","Tehlike","Xavf"],["15","Yetkili","Mas’ul xodim"],["16","Yönetici","Rahbar"],["17","Görevli","Xodim / mas’ul shaxs"],["18","Ambulans","Tez yordam"],["19","Polis","Politsiya"],["20","Hastane","Kasalxona"],["21","Doktor","Shifokor"],["22","Yaralanma","Jarohat"],["23","Rahatsızlık","Betoblik / noqulaylik"],["24","Kayıp","Yo‘qotish"],["25","Kayıp eşya","Yo‘qolgan buyum"],["26","İletişim","Aloqa"],["27","Kontrol","Tekshiruv"],["28","Bildirmek","Xabar bermoq"],["29","Çözmek","Hal qilmoq"],["30","Sakin","Xotirjam"]],"phrases":[["1","Yaşadığınız sorun için özür dilerim.","Siz duch kelgan muammo uchun uzr so‘rayman."],["2","Sizi anlıyorum.","Sizni tushunaman."],["3","Şikâyetinizi dikkatle dinliyorum.","Shikoyatingizni diqqat bilan tinglayapman."],["4","Lütfen sakin olun.","Iltimos, xotirjam bo‘ling."],["5","Öncelikle durumu kontrol edelim.","Avvalo vaziyatni tekshirib olaylik."],["6","Tam olarak ne oldu?","Aniq nima bo‘ldi?"],["7","Sorun ne zaman başladı?","Muammo qachon boshlandi?"],["8","Hemen ilgileniyorum.","Darhol shug‘ullanaman."],["9","Yetkili kişiye haber vereceğim.","Mas’ul xodimga xabar beraman."],["10","Yöneticimizle görüşeceğim.","Rahbarimiz bilan gaplashaman."],["11","Size alternatif bir çözüm sunabiliriz.","Sizga muqobil yechim taklif qilishimiz mumkin."],["12","Bu sorunu mümkün olduğunca hızlı çözmeye çalışacağım.","Bu muammoni imkon qadar tez hal qilishga harakat qilaman."],["13","Birkaç dakika beklemenizi rica ediyorum.","Bir necha daqiqa kutishingizni so‘rayman."],["14","Konuyu ilgili departmana ileteceğim.","Masalani tegishli bo‘limga yetkazaman."],["15","Durum hakkında size bilgi vereceğim.","Vaziyat haqida sizga ma’lumot beraman."],["16","Beklettiğimiz için özür dileriz.","Kuttirganimiz uchun uzr so‘raymiz."],["17","Bu durum bizim için de önemli.","Bu vaziyat biz uchun ham muhim."],["18","Mağduriyetinizi anlıyorum.","Sizning noqulay holatingizni tushunaman."],["19","Gerekli işlemleri başlatacağız.","Kerakli ishlarni boshlaymiz."],["20","Lütfen burada bekleyin.","Iltimos, shu yerda kuting."],["21","Güvenli bir yerde bekleyelim.","Xavfsiz joyda kutaylik."],["22","Acil yardım çağırmamız gerekiyor.","Tez yordam chaqirishimiz kerak."],["23","Ambulans çağırıyorum.","Tez yordam chaqiryapman."],["24","Polisle iletişime geçeceğiz.","Politsiya bilan bog‘lanamiz."],["25","Kendinizi iyi hissediyor musunuz?","O‘zingizni yaxshi his qilyapsizmi?"],["26","Herhangi bir yeriniz ağrıyor mu?","Biror joyingiz og‘riyaptimi?"],["27","Lütfen hareket etmeyin.","Iltimos, harakat qilmang."],["28","Yardım hemen geliyor.","Yordam hozir keladi."],["29","Sorununuz çözüldü mü?","Muammongiz hal bo‘ldimi?"],["30","Anlayışınız için teşekkür ederim.","Tushunganingiz uchun rahmat."]],"dialogs":[{"title":"DİYALOG 1 — OTEL ODASIYLA İLGİLİ ŞİKÂYET","lines":["Müşteri: Merhaba. Odamızla ilgili bir şikâyetimiz var.","Çalışan: Merhaba. Tabii, sizi dinliyorum. Sorun nedir?","Müşteri: Oda çok gürültülü. Gece uyuyamadık.","Çalışan: Yaşadığınız sorun için özür dilerim. Odanız hangi tarafta?","Müşteri: Asansörün yanında.","Çalışan: Anladım. Oda değişikliği sizin için uygun olur mu?","Müşteri: Eğer daha sessiz bir oda varsa, evet.","Çalışan: Hemen müsait odaları kontrol ediyorum.","Müşteri: Teşekkür ederim.","Çalışan: Birkaç dakika beklemenizi rica ediyorum.","Müşteri: Tamam.","Çalışan: Sizin için daha sessiz bir oda bulduk. Odayı değiştirebiliriz.","Müşteri: Çok iyi olur.","Çalışan: Tekrar özür dilerim. Umarım yeni odanızdan memnun kalırsınız."]},{"title":"DİYALOG 2 — TRANSFERİN GECİKMESİ","lines":["Müşteri: Transfer aracımız hâlâ gelmedi.","Görevli: Özür dilerim. Transfer saatiniz kaçtı?","Müşteri: Saat dokuzdu. Şimdi saat dokuz buçuk.","Görevli: Hemen kontrol ediyorum.","Müşteri: Uçağımıza geç kalmaktan korkuyoruz.","Görevli: Endişenizi anlıyorum. Şoförle hemen iletişime geçeceğim.","Müşteri: Araç ne zaman gelecek?","Görevli: Bir dakika, bilgi alıyorum.","Müşteri: Tamam.","Görevli: Şoför trafik nedeniyle gecikmiş. Araç yaklaşık on dakika içinde burada olacak.","Müşteri: On dakika daha bekleyebilir miyiz?","Görevli: Evet, havaalanına zamanında ulaşmanız için alternatif bir araç da kontrol ediyorum.","Müşteri: Çok iyi olur.","Görevli: Sizi mağdur etmemek için gerekli işlemleri hemen yapacağım."]},{"title":"DİYALOG 3 — RESTORANDA CİDDİ BİR ŞİKÂYET","lines":["Müşteri: Bu restoranda hizmetten hiç memnun kalmadım.","Garson: Bunu duyduğuma üzüldüm. Yaşadığınız sorunu anlatabilir misiniz?","Müşteri: Siparişimiz çok geç geldi ve yemek de soğuktu.","Garson: Yaşadığınız sorun için özür dilerim.","Müşteri: Ayrıca hesabımızda yanlışlık var.","Garson: Hemen hesabı kontrol edeyim.","Müşteri: Tamam.","Garson: Evet, burada bir hata olmuş. Fazladan bir ürün eklenmiş.","Müşteri: Peki yemek konusunda ne yapabiliriz?","Garson: İsterseniz yeni bir yemek hazırlatabiliriz.","Müşteri: Ne kadar sürecek?","Garson: Yaklaşık on dakika.","Müşteri: Tamam.","Garson: Ayrıca hesabınızdaki hatayı hemen düzelteceğim. Yaşadığınız sorun için tekrar özür dilerim.","Müşteri: Teşekkür ederim.","Garson: Rica ederim."]},{"title":"DİYALOG 4 — MİSAFİRİN KENDİNİ KÖTÜ HİSSETMESİ","lines":["Müşteri: Yardım eder misiniz? Kendimi çok kötü hissediyorum.","Çalışan: Tabii. Lütfen sakin olun. Kendinizi nasıl hissediyorsunuz?","Müşteri: Başım dönüyor ve çok halsizim.","Çalışan: Şu anda oturmak ister misiniz?","Müşteri: Evet, lütfen.","Çalışan: Tabii. Güvenli bir yerde oturalım.","Müşteri: Teşekkür ederim.","Çalışan: Eğer durumunuz devam ederse acil yardım çağırmamız gerekebilir.","Müşteri: Ambulans çağırabilir misiniz?","Çalışan: Elbette. Hemen ambulans çağırıyorum.","Müşteri: Çok teşekkür ederim.","Çalışan: Rica ederim. Yardım gelene kadar yanınızda kalacağım.","Müşteri: Tamam.","Çalışan: Lütfen sakin olun. Yardım birazdan burada olacak."]}],"grammar":["GRAMER — ŞİKÂYET VE ACİL DURUMLARDA TÜRKÇE","Bu mavzuda muammoli vaziyatni aniq ifodalash, mijozning muammosi davom etayotganini aytish, ehtiyotkorlik bilan savol berish va bajarilishi kerak bo‘lgan ishlarni ifodalash uchun kerakli grammatikalar beriladi.","5.1. “-DIĞINI / -DİĞİNİ” — ...GANINI","Biror fikr yoki xabarni “...ganini” shaklida boshqa kishiga yetkazishda ishlatiladi.","Örnekler:","Müşteri odanın çok gürültülü olduğunu söyledi.\n— Mijoz xona juda shovqinli ekanini aytdi.","Şoförün geciktiğini öğrendik.\n— Haydovchi kechikkanini bildik.","Misafirin kendini kötü hissettiğini söylediler.\n— Mehmon o‘zini yomon his qilayotganini aytishdi.","5.2. “-MEKTE / -MAKTA” — HOZIR DAVOM ETAYOTGAN RASMIY HARAKAT","Bu shakl “-iyor”ga o‘xshaydi, lekin rasmiy va professional tilda ko‘proq uchraydi.","Örnekler:","Konuyu araştırmaktayız.\n— Masalani o‘rganmoqdamiz.","Yetkili kişi sizinle görüşmekte.\n— Mas’ul shaxs siz bilan gaplashmoqda.","Ekip sorunu çözmekte.\n— Jamoa muammoni hal qilmoqda.","Eslatma: Kundalik suhbatda ko‘pincha -iyor, rasmiy xizmat tilida esa -mekte/-makta ishlatiladi.","5.3. “-MAYA ÇALIŞMAK” — ...GA HARAKAT QILMOQ","Biror ishni amalga oshirishga urinish yoki harakat qilishni bildiradi.","Örnekler:","Sorunu en kısa sürede çözmeye çalışacağım.\n— Muammoni imkon qadar tez hal qilishga harakat qilaman.","Size uygun bir çözüm bulmaya çalışıyoruz.\n— Sizga mos yechim topishga harakat qilyapmiz.","Müşterinin mağduriyetini gidermeye çalışıyoruz.\n— Mijozning noqulay holatini bartaraf etishga harakat qilyapmiz.","5.4. “-DIĞI SÜRECE” — ...GAN EKAN / ...GAN PAYTGACHA","Biror shart davom etayotgan vaqtni bildiradi.","Örnekler:","Sorun devam ettiği sürece sizinle iletişimde olacağız.\n— Muammo davom etayotgan ekan, siz bilan aloqada bo‘lamiz.","Güvenliğiniz sağlandığı sürece burada bekleyebilirsiniz.\n— Xavfsizligingiz ta’minlangan ekan, bu yerda kutishingiz mumkin.","Durum kontrol altında olduğu sürece endişelenmenize gerek yok.\n— Vaziyat nazorat ostida ekan, xavotirlanishingiz shart emas.","5.5. “-MEK GEREKİYOR” — ...ISH KERAK / ZARUR","Zaruriyatni professional tarzda ifodalashda ishlatiladi.","Örnekler:","Ambulans çağırmak gerekiyor.\n— Tez yordam chaqirish kerak.","Yetkili kişiye haber vermek gerekiyor.\n— Mas’ul xodimga xabar berish kerak.","Rezervasyonu tekrar kontrol etmek gerekiyor.\n— Rezervatsiyani yana tekshirish kerak.","Müşteriye bilgi vermek gerekiyor.\n— Mijozga ma’lumot berish kerak."],"video":"https://youtu.be/4HcpC7-STnc?si=0WRoT0EisYokuJIn","document":"assets/materials/day14.docx"},{"day":15,"title":"GİRİŞ","subtitle":"Turizm sektöründe iletişim sadece yüz yüze gerçekleşmez. Otel, seyahat acentesi, restoran, transfer şirketi ve tur operatörlerinde telefon görüşmeleri, WhatsApp mesajları ve diğer yazılı iletişim kanalları günlük iş hayatının önemli bir parçasıdır.","words":[["1","Telefon görüşmesi","Telefon orqali suhbat"],["2","Telefon numarası","Telefon raqami"],["3","Mesaj","Xabar"],["4","WhatsApp","WhatsApp"],["5","E-posta","Elektron pochta"],["6","Aramak","Qo‘ng‘iroq qilmoq"],["7","Cevaplamak","Javob bermoq"],["8","Görüşmek","Gaplashmoq"],["9","Yazmak","Yozmoq"],["10","Göndermek","Yubormoq"],["11","İletmek","Yetkazmoq"],["12","Onaylamak","Tasdiqlamoq"],["13","Bilgilendirmek","Ma’lumot bermoq"],["14","Hatırlatmak","Eslatmoq"],["15","Doğrulamak","Tasdiqlab tekshirmoq"],["16","Rezervasyon","Rezervatsiya"],["17","Onay","Tasdiq"],["18","Değişiklik","O‘zgarish"],["19","İptal","Bekor qilish"],["20","Tarih","Sana"],["21","Saat","Vaqt / soat"],["22","Adres","Manzil"],["23","Konum","Joylashuv"],["24","Belge","Hujjat"],["25","Bilgi","Ma’lumot"],["26","Ek","Ilova"],["27","Dosya","Fayl"],["28","Bağlantı","Havola"],["29","Ulaşmak","Bog‘lanmoq / yetib bormoq"],["30","Geri dönüş","Qayta aloqa / javob"]],"phrases":[["1","Merhaba, size nasıl yardımcı olabilirim?","Salom, sizga qanday yordam bera olaman?"],["2","Buyurun, sizi dinliyorum.","Marhamat, sizni tinglayapman."],["3","Kiminle görüşüyorum?","Kim bilan gaplashyapman?"],["4","Hangi konuda aramıştınız?","Qaysi masala bo‘yicha qo‘ng‘iroq qilgandingiz?"],["5","Bir dakika, bilgilerinizi kontrol edeyim.","Bir daqiqa, ma’lumotlaringizni tekshiray."],["6","Rezervasyon numaranızı alabilir miyim?","Rezervatsiya raqamingizni olsam bo‘ladimi?"],["7","Telefon numaranızı tekrar alabilir miyim?","Telefon raqamingizni yana olsam bo‘ladimi?"],["8","Bilgileri WhatsApp üzerinden gönderebilirim.","Ma’lumotlarni WhatsApp orqali yuborishim mumkin."],["9","Size konum bilgisi göndereceğim.","Sizga joylashuv ma’lumotini yuboraman."],["10","Rezervasyon bilgilerinizi mesaj olarak ileteceğim.","Rezervatsiya ma’lumotlaringizni xabar sifatida yuboraman."],["11","Mesajınızı aldım.","Xabaringizni oldim."],["12","Mesajınıza en kısa sürede cevap vereceğim.","Xabaringizga imkon qadar tez javob beraman."],["13","Bilgilerinizi kontrol edip size dönüş yapacağım.","Ma’lumotlaringizni tekshirib, sizga qayta javob beraman."],["14","Rezervasyonunuzu onaylıyoruz.","Rezervatsiyangizni tasdiqlaymiz."],["15","Rezervasyonunuz onaylandı.","Rezervatsiyangiz tasdiqlandi."],["16","Rezervasyon bilgilerinde bir değişiklik oldu.","Rezervatsiya ma’lumotlarida o‘zgarish bo‘ldi."],["17","Tarihi değiştirmemiz gerekiyor.","Sanani o‘zgartirishimiz kerak."],["18","Transfer saatiniz değişti.","Transfer vaqtingiz o‘zgardi."],["19","Lütfen yeni saati kontrol edin.","Iltimos, yangi vaqtni tekshiring."],["20","Bu bilgiyi size e-posta ile göndereceğim.","Bu ma’lumotni sizga e-mail orqali yuboraman."],["21","Dosyayı mesajın ekinde bulabilirsiniz.","Faylni xabarning ilovasida topishingiz mumkin."],["22","Size gerekli belgeleri gönderdim.","Sizga kerakli hujjatlarni yubordim."],["23","Lütfen bilgileri kontrol edip onaylayın.","Iltimos, ma’lumotlarni tekshirib tasdiqlang."],["24","Herhangi bir yanlışlık varsa bize bildirin.","Biror xato bo‘lsa, bizga xabar bering."],["25","Şu anda müsait değilim, size daha sonra döneceğim.","Hozir bo‘sh emasman, keyinroq sizga qaytaman."],["26","Görüşmemiz gerekiyor.","Gaplashishimiz kerak."],["27","Sizi birazdan tekrar arayacağım.","Sizga birozdan yana qo‘ng‘iroq qilaman."],["28","İlginiz için teşekkür ederiz.","Qiziqishingiz uchun rahmat."],["29","Bizi tercih ettiğiniz için teşekkür ederiz.","Bizni tanlaganingiz uchun rahmat."],["30","İyi günler dilerim.","Kuningiz xayrli o‘tsin."]],"dialogs":[{"title":"DİYALOG 1 — TELEFONDA REZERVASYON SORGULAMA","lines":["Müşteri: Merhaba, otelinizde bir rezervasyon yapmak istiyorum.","Çalışan: Merhaba, tabii. Size nasıl yardımcı olabilirim?","Müşteri: Gelecek ay beş gün kalmak istiyorum.","Çalışan: Tabii. Giriş ve çıkış tarihlerinizi öğrenebilir miyim?","Müşteri: 10 Kasım'da giriş, 15 Kasım'da çıkış yapacağım.","Çalışan: Kaç kişi konaklayacaksınız?","Müşteri: İki yetişkin olacağız.","Çalışan: Bir dakika, müsaitliği kontrol ediyorum.","Müşteri: Tamam.","Çalışan: Evet, bu tarihlerde standart odamız müsait.","Müşteri: Kahvaltı dahil mi?","Çalışan: Evet, kahvaltı fiyata dahildir.","Müşteri: Rezervasyonu telefonla yapabilir miyim?","Çalışan: Elbette. Bilgilerinizi aldıktan sonra rezervasyonunuzu oluşturabiliriz.","Müşteri: Teşekkür ederim.","Çalışan: Rica ederim. Rezervasyon bilgilerinizi WhatsApp üzerinden de gönderebiliriz."]},{"title":"DİYALOG 2 — WHATSAPP ÜZERİNDEN TRANSFER BİLGİSİ","lines":["Müşteri: Merhaba. Yarınki havaalanı transferim hakkında bilgi almak istiyorum.","Çalışan: Merhaba. Tabii. Rezervasyon numaranızı paylaşabilir misiniz?","Müşteri: Evet, rezervasyon numaram 4582.","Çalışan: Teşekkür ederim. Kontrol ediyorum.","Müşteri: Tamam.","Çalışan: Transferiniz yarın saat 08.30'da otelin önünden hareket edecek.","Müşteri: Şoförü nerede bulacağım?","Çalışan: Şoför otelin ana girişinde sizi bekleyecek.","Müşteri: Şoförün telefon numarasını alabilir miyim?","Çalışan: Elbette. Bilgileri size WhatsApp üzerinden göndereceğim.","Müşteri: Çok teşekkür ederim.","Çalışan: Rica ederim. Ayrıca konum bilgisini de mesaj olarak göndereceğim.","Müşteri: Harika. Teşekkürler.","Çalışan: İyi yolculuklar dilerim."]},{"title":"DİYALOG 3 — REZERVASYONDA DEĞİŞİKLİK","lines":["Müşteri: Merhaba. Rezervasyonumda bir değişiklik yapmak istiyorum.","Çalışan: Tabii. Rezervasyon numaranızı alabilir miyim?","Müşteri: 7821.","Çalışan: Teşekkür ederim. Rezervasyonunuzu kontrol ediyorum.","Müşteri: Giriş tarihimi iki gün değiştirmek istiyorum.","Çalışan: Mevcut tarihiniz 15 Temmuz. Yeni giriş tarihi hangi gün olacak?","Müşteri: 17 Temmuz.","Çalışan: Bir dakika, yeni tarihte müsaitliği kontrol edeyim.","Müşteri: Tamam.","Çalışan: Evet, 17 Temmuz için odamız müsait.","Müşteri: Çok iyi.","Çalışan: Değişikliği şimdi yapıyorum.","Müşteri: Yeni rezervasyon bilgilerini bana gönderebilir misiniz?","Çalışan: Elbette. Güncellenmiş bilgileri WhatsApp ve e-posta üzerinden göndereceğim.","Müşteri: Teşekkür ederim.","Çalışan: Rica ederim. Lütfen mesajı aldıktan sonra bilgileri kontrol edin."]},{"title":"DİYALOG 4 — TELEFONDA YANLIŞ BİLGİ","lines":["Müşteri: Merhaba. Bana gönderdiğiniz rezervasyon belgesinde yanlışlık var.","Çalışan: Merhaba. Elbette, hemen kontrol edelim. Hangi bilgide hata var?","Müşteri: Çıkış tarihi yanlış yazılmış.","Çalışan: Anladım. Doğru çıkış tarihiniz nedir?","Müşteri: 25 Ağustos.","Çalışan: Bir dakika, sistemdeki bilgileri kontrol ediyorum.","Müşteri: Tamam.","Çalışan: Evet, gerçekten bir hata olmuş. Özür dilerim.","Müşteri: Sorun değil, ama doğru belgeye ihtiyacım var.","Çalışan: Tabii. Bilgiyi şimdi düzeltiyorum.","Müşteri: Ne zaman gönderebilirsiniz?","Çalışan: Düzeltilmiş belgeyi birkaç dakika içinde size e-posta ile göndereceğim.","Müşteri: Tamam, teşekkür ederim.","Çalışan: Rica ederim. Belgeyi aldıktan sonra tekrar kontrol etmenizi rica ederim."]}],"grammar":["GRAMER — TELEFON VE YAZILI İLETİŞİMDE KULLANILAN YAPILAR","Bu mavzuda yozma va telefon muloqotida fikrni qanday usulda bajarish, ma’lumotni nimaga bog‘lash, bir ishni boshqa ish bilan birga bajarish va biror mavzu haqida gapirish uchun kerakli grammatik shakllar o‘rganiladi.","5.1. “-İP / -IP / -UP / -ÜP” — ...IB","Bir nechta harakatni ketma-ket bog‘lash uchun ishlatiladi.","Örnekler:","Bilgilerinizi kontrol edip size dönüş yapacağım.\n— Ma’lumotlaringizni tekshirib, sizga qayta javob beraman.","Rezervasyonu kontrol edip mesaj gönderdim.\n— Rezervatsiyani tekshirib, xabar yubordim.","Müşteri arayıp bilgi aldı.\n— Mijoz qo‘ng‘iroq qilib, ma’lumot oldi.","5.2. “-ARAK / -EREK” — ...IB / ...GAN HOLDA","Biror ishning qanday usulda bajarilayotganini ko‘rsatadi.","Örnekler:","Müşteriye WhatsApp üzerinden mesaj göndererek bilgi verdik.\n— Mijozga WhatsApp orqali xabar yuborib, ma’lumot berdik.","Telefonla görüşerek rezervasyonu doğruladık.\n— Telefon orqali gaplashib, rezervatsiyani tasdiqladik.","E-posta göndererek belgeleri ilettik.\n— E-mail yuborib, hujjatlarni yetkazdik.","5.3. “-CE / -CA” — ...CHA / ... TARZDA","Bu qo‘shimcha ish-harakatning qanday tarzda bajarilishini bildiradi.","Örnekler:","Resmî olarak bilgi vereceğiz.\n— Rasmiy tarzda ma’lumot beramiz.","Yazılı olarak onay gönderebiliriz.\n— Yozma tarzda tasdiq yuborishimiz mumkin.","Sözlü olarak bilgi vermek yeterli değil.\n— Og‘zaki ma’lumot berish yetarli emas.","5.4. “-İLE İLGİLİ” — ... HAQIDA / ... BILAN BOG‘LIQ","Biror mavzu yoki masala haqida gapirishda ishlatiladi.","Örnekler:","Rezervasyonunuzla ilgili bir mesaj gönderdim.\n— Rezervatsiyangiz haqida xabar yubordim.","Transferinizle ilgili bilgi vereceğim.\n— Transferingiz haqida ma’lumot beraman.","Tur programıyla ilgili sorunuz var mı?\n— Tur dasturi haqida savolingiz bormi?","5.5. “-HAKKINDA” — ... HAQIDA","Biror mavzu to‘g‘risida ma’lumot berish yoki savol berishda ishlatiladi.","Örnekler:","Otel hakkında bilgi almak istiyorum.\n— Mehmonxona haqida ma’lumot olmoqchiman.","Transfer hakkında size mesaj göndereceğim.\n— Transfer haqida sizga xabar yuboraman.","Rezervasyon hakkında bir sorunuz var mı?\n— Rezervatsiya haqida savolingiz bormi?","“İle ilgili” va “hakkında” ko‘p holatlarda bir-biriga yaqin ma’noda ishlatiladi:","Rezervasyonla ilgili bilgi vereceğim.","Rezervasyon hakkında bilgi vereceğim.","Ikkalasi ham: “Rezervatsiya haqida ma’lumot beraman.”"],"video":"https://youtu.be/vkgsDeSfiCI?si=DNTVd4_MfDZY1WWD","document":"assets/materials/day15.docx"}];
